window.CONTENT=window.CONTENT||{};window.CONTENT.ict=window.CONTENT.ict||{};
window.CONTENT.ict[6]=[{"t":"1-dars. Matn qo‘shish, o‘zgartrish va ko‘chirish","lesson":"<p>Matnli muharrirda hujjat bilan ishlashning asosi — <b>matn qo‘shish</b>, uni <b>o‘zgartirish</b> va <b>ko‘chirish</b>. Matn <b>kursor</b> (yonib-o‘chib turuvchi vertikal chiziqcha) turgan joyga yoziladi.</p>\n<h4>Asosiy amallar</h4>\n<ul><li><b>Matn qo‘shish:</b> kursorni kerakli joyga qo‘yib, klaviaturadan yoziladi.</li><li><b>O‘zgartirish:</b> kerakli so‘z yoki jumla belgilanadi va ustidan yangisi yoziladi, yoki xato harflar o‘chirib tuzatiladi.</li><li><b>Ko‘chirish:</b> matn belgilanadi, kesib olinadi (Cut) va boshqa joyga qo‘yiladi (Paste).</li><li><b>Nusxalash (Copy):</b> asl matn joyida qoladi, nusxasi boshqa joyga qo‘yiladi.</li></ul>\n<div class=\"ex\"><b>Amaliy topshiriq.</b><ol><li>Yangi hujjat oching va 3 qatorli kichik matn yozing.</li><li>Ikkinchi qatorni belgilab, uni birinchi qator tepasiga ko‘chiring.</li><li>Bitta so‘zni boshqasiga almashtiring.</li></ol></div>\n<h4>Eslab qoling</h4><ul><li>Cut matnni asl joyidan olib tashlaydi, Copy esa qoldiradi.</li><li>Qo‘yishdan oldin kursor kerakli joyda bo‘lishi kerak.</li><li>Xato qilsangiz, bekor qilish (Undo) tugmasidan foydalaning.</li></ul>","quiz":[{"q":"Matn hujjatda qayerga yoziladi?","o":["Har doim birinchi qatorga","Kursor turgan joyga","Sichqoncha ko‘rsatkichi turgan joyga","Har doim oxirgi qatorga"],"a":1,"e":"Yozilgan belgilar kursor turgan o‘ringa qo‘yiladi."},{"q":"Matnni bir joydan olib, boshqa joyga o‘tkazish (asl joyidan o‘chirish) qaysi amal?","o":["Chop etish","Nusxalash (Copy)","Saqlash","Ko‘chirish (Cut va Paste)"],"a":3,"e":"Cut matnni asl joyidan olib tashlaydi, Paste esa yangi joyga qo‘yadi."},{"q":"Copy amalidan keyin asl matn nima bo‘ladi?","o":["Joyida qoladi","Yashirinadi","Qalin shriftga o‘tadi","O‘chib ketadi"],"a":0,"e":"Copy faqat nusxa oladi, asl matn o‘zgarmaydi."},{"q":"Matnni ko‘chirishdan oldin birinchi navbatda nima qilish kerak?","o":["Matnni belgilash","Shriftni o‘zgartirish","Dasturni yopish","Hujjatni saqlash"],"a":0,"e":"Avval kerakli matn belgilanadi, so‘ng Cut yoki Copy bajariladi."},{"q":"Kursor qanday ko‘rinishda bo‘ladi?","o":["Qizil to‘rtburchak","Yonib-o‘chib turuvchi vertikal chiziqcha","Doimiy gorizontal chiziq","Ikki tomonlama strelka"],"a":1,"e":"Matn kiritish joyini kursor ko‘rsatadi."},{"q":"Yozilgan matndagi xatoni tuzatishning to‘g‘ri yo‘li qaysi?","o":["Butun hujjatni o‘chirish","Hujjatni yopib, qayta ochish","Xato so‘zni belgilab, to‘g‘risini yozish","Kompyuterni qayta yoqish"],"a":2,"e":"Xato joyni belgilab yoki o‘chirib, to‘g‘risini yozish kifoya."},{"q":"Noto‘g‘ri bajarilgan amalni bekor qilish uchun nima ishlatiladi?","o":["Undo (Bekor qilish)","Print","Paste","Save as"],"a":0,"e":"Undo oxirgi bajarilgan amalni qaytaradi."},{"q":"Paste (Qo‘yish) amali nima qiladi?","o":["Matnni o‘chiradi","Xotirada turgan matnni kursor joyiga qo‘yadi","Matnni belgilaydi","Hujjatni chop etadi"],"a":1,"e":"Cut yoki Copy qilingan matn Paste bilan joylashtiriladi."},{"q":"Bir xil gapni hujjatda yana bir marta yozish uchun eng qulay usul qaysi?","o":["Hammasini qaytadan terish shart","Hujjatni yangidan ochish","Shriftni kattalashtirish","Gapni belgilab, Copy va Paste qilish"],"a":3,"e":"Nusxalash vaqtni tejaydi va xato ehtimolini kamaytiradi."},{"q":"Quyidagilardan qaysi biri matn ustida bajariladigan amal EMAS?","o":["Ko‘chirish","Monitor yorqinligini o‘zgartirish","Tahrirlash","Nusxalash"],"a":1,"e":"Monitor yorqinligi qurilma sozlamasi, matn amali emas."}]},{"t":"2-dars. Shrift turi, o‘lchami va rangini o‘zgartrish. Matnni tekislash","lesson":"<p>Hujjat chiroyli va o‘qishga qulay bo‘lishi uchun matn <b>formatlanadi</b>: shrift turi, o‘lchami, rangi o‘zgartiriladi va matn tekislanadi.</p>\n<h4>Shrift sozlamalari</h4>\n<ul><li><b>Shrift turi</b> — harflarning ko‘rinishi (masalan, Times New Roman, Arial).</li><li><b>Shrift o‘lchami</b> — harflar kattaligi (punktlarda o‘lchanadi).</li><li><b>Shrift rangi</b> — harflar rangi.</li><li><b>Uslub:</b> qalin, kursiv va tagiga chizilgan.</li></ul>\n<h4>Matnni tekislash</h4>\n<ul><li><b>Chap chetga</b> — qatorlar chap tomondan tekis boshlanadi.</li><li><b>O‘rtaga</b> — sarlavhalar uchun qulay.</li><li><b>O‘ng chetga</b> — qatorlar o‘ng tomondan tekis tugaydi.</li><li><b>Ikki chetga</b> — qatorlar ikkala tomondan tekis bo‘ladi.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Sarlavhani belgilab, o‘lchamini kattalashtiramiz, qalin qilamiz va o‘rtaga tekislaymiz. Asosiy matnni esa chap yoki ikki chetga tekislaymiz.</div>\n<h4>Eslab qoling</h4><ul><li>Avval matnni belgilang, keyin formatlang.</li><li>Hujjatda juda ko‘p xil shrift ishlatish ko‘rinishni buzadi.</li></ul>","quiz":[{"q":"Formatlashdan oldin matn bilan nima qilish kerak?","o":["Nusxa olish","Chop etish","Belgilash","Saqlash"],"a":2,"e":"Format faqat belgilangan matnga qo‘llanadi."},{"q":"Harflar kattaligi nima deyiladi?","o":["Abzas","Shrift o‘lchami","Shrift turi","Tekislash"],"a":1,"e":"Harf kattaligi shrift o‘lchami bilan beriladi."},{"q":"Sarlavhani odatda qanday tekislash qulay?","o":["Tekislab bo‘lmaydi","O‘rtaga","Faqat o‘ng chetga","Har safar turlicha"],"a":1,"e":"Sarlavhalar ko‘pincha o‘rtaga joylashtiriladi."},{"q":"Arial va Times New Roman nimani bildiradi?","o":["Tekislash usullarini","Shrift turlarini","Dastur nomlarini","Rang nomlarini"],"a":1,"e":"Bu nomlar harflarning ko‘rinishi, ya’ni shrift turini bildiradi."},{"q":"Matnning ikkala chetidan ham tekis bo‘lishini ta’minlaydigan tekislash qaysi?","o":["O‘rtaga","Ikki chetga","O‘ng chetga","Chap chetga"],"a":1,"e":"Ikki chetga tekislashda qatorlar ikki tomondan teng bo‘ladi."},{"q":"Qalin (Bold) uslubi matnga nima qiladi?","o":["Matnni tagiga chizadi","Harflarni yo‘g‘onroq ko‘rsatadi","Matnni o‘chiradi","Harflarni og‘ma qiladi"],"a":1,"e":"Qalin uslub harflarni yo‘g‘on qilib ko‘rsatadi."},{"q":"Og‘ma harflar qaysi uslubga to‘g‘ri keladi?","o":["Qalin","Kichik harf","Kursiv","Tagiga chizilgan"],"a":2,"e":"Kursiv — og‘ma yozuv uslubi."},{"q":"Matn rangini o‘zgartirish nimani o‘zgartiradi?","o":["Fayl nomini","Qog‘oz turini","Harflar rangini","Sahifa o‘lchamini"],"a":2,"e":"Shrift rangi harflar rangini belgilaydi."},{"q":"Hujjatni o‘qishga qulay qilish uchun qaysi tavsiya to‘g‘ri?","o":["Bir-ikki xil shrift va mos o‘lcham tanlash","Har so‘zga boshqa shrift berish","Eng kichik o‘lchamni tanlash","Barcha matnni qizil qilish"],"a":0,"e":"Bir xillik va o‘qilish qulayligi muhim."},{"q":"Qatorlar chap tomondan tekis boshlanishi uchun qanday tekislash tanlanadi?","o":["Ikki chetga","O‘rtaga","O‘ng chetga","Chap chetga"],"a":3,"e":"Chap chetga tekislashda qatorlar chapdan tekis boshlanadi."}]},{"t":"3-dars. Hujjatga tasvir va hoshiya qo‘shish","lesson":"<p>Hujjatni yanada ma’lumotli va ko‘rkam qilish uchun unga <b>tasvir</b> va <b>hoshiya</b> qo‘shish mumkin.</p>\n<h4>Tasvir qo‘shish</h4>\n<ul><li>Kursor tasvir turishi kerak bo‘lgan joyga qo‘yiladi.</li><li>Tasvir qo‘shish (Insert / Picture) buyrug‘i tanlanadi va kompyuterdagi rasm fayli ko‘rsatiladi.</li><li>Tasvir hujjatga kiritilgach, uning burchaklaridagi nuqtalarni tortib o‘lchamini o‘zgartirish mumkin.</li></ul>\n<h4>Hoshiya qo‘shish</h4>\n<ul><li><b>Hoshiya</b> — matn yoki tasvir atrofidagi ramka chiziq.</li><li>Uning turi, rangi va qalinligini tanlash mumkin.</li><li>Hoshiya butun sahifaga ham, alohida abzas yoki rasmga ham beriladi.</li></ul>\n<div class=\"ex\"><b>Amaliy topshiriq.</b><ol><li>«Mening maktabim» hujjatini yarating.</li><li>Unga maktabingiz haqida 3 jumla va bitta rasm qo‘shing.</li><li>Rasmga hoshiya bering.</li></ol></div>\n<h4>Eslab qoling</h4><ul><li>Tasvir o‘lchamini burchak nuqtalaridan tortgan ma’qul, shunda u cho‘zilib ketmaydi.</li><li>Tasvir matn mazmuniga mos bo‘lishi kerak.</li></ul>","quiz":[{"q":"Hoshiya nima?","o":["Matn yoki tasvir atrofidagi ramka chiziq","Sahifa raqami","Hujjat nomi","Shrift turi"],"a":0,"e":"Hoshiya ob’ekt atrofiga chizilgan ramkadir."},{"q":"Hujjatga tasvir qo‘shish uchun qaysi buyruq ishlatiladi?","o":["Insert (Qo‘yish) bo‘limidagi Picture","Spelling","Undo","Print"],"a":0,"e":"Tasvir Insert bo‘limidagi Picture yordamida qo‘shiladi."},{"q":"Tasvir hujjatning kerakli joyiga tushishi uchun qanday ish qilinadi?","o":["Dastur qayta yoqiladi","Avval hujjat chop etiladi","Avval kursor shu joyga qo‘yiladi","Hoshiya o‘chiriladi"],"a":2,"e":"Tasvir kursor turgan joyga qo‘shiladi."},{"q":"Tasvir o‘lchamini cho‘zmasdan o‘zgartirish uchun nimadan tortiladi?","o":["Sarlavhadan","Faqat yon tomon nuqtasidan","Fayl nomidan","Burchak nuqtalaridan"],"a":3,"e":"Burchak nuqtalari tasvir nisbatini saqlagan holda o‘lchamni o‘zgartiradi."},{"q":"Hoshiyaning qaysi xususiyatlarini tanlash mumkin?","o":["Turi, rangi va qalinligi","Faqat nomi","Faqat joyi","Faqat fayl hajmi"],"a":0,"e":"Hoshiya turi, rangi va qalinligi sozlanadi."},{"q":"Hoshiyani qayerga berish mumkin?","o":["Faqat fayl nomiga","Faqat monitorga","Rasmga, abzasga yoki butun sahifaga","Faqat klaviaturaga"],"a":2,"e":"Hoshiya turli ob’ektlar va butun sahifa uchun beriladi."},{"q":"Hujjatga qo‘shiladigan tasvir qanday bo‘lishi kerak?","o":["Eng katta hajmli","Doim bir xil","Matn mazmuniga mos","Albatta qora-oq"],"a":2,"e":"Tasvir hujjat mavzusini to‘ldirishi lozim."},{"q":"Tasvirlar qayerdan olinib hujjatga qo‘shiladi?","o":["Faqat monitordan","Kompyuterdagi rasm faylidan","Faqat printerdan","Faqat sichqonchadan"],"a":1,"e":"Rasm fayli ko‘rsatilib, hujjatga kiritiladi."},{"q":"«Mening maktabim» hujjati uchun eng mos tasvir qaysi?","o":["Bo‘sh oq kvadrat","Boshqa shahar xaritasi","Tasodifiy mashina rasmi","Maktab binosi rasmi"],"a":3,"e":"Tasvir hujjat mavzusiga mos bo‘lishi kerak."},{"q":"Hoshiya hujjatning nimasini yaxshilaydi?","o":["Fayl hajmini nolga tushiradi","Klaviatura tezligini","Internet tezligini","Tashqi ko‘rinishini"],"a":3,"e":"Hoshiya ob’ektni ajratib, hujjatni ko‘rkamroq qiladi."}]},{"t":"4-dars. Hujjatlarni auditoriya uchun moslash","lesson":"<p>Har bir hujjat o‘z o‘quvchisiga, ya’ni <b>auditoriyaga</b> mo‘ljallanadi. Kichik bolalar uchun, rahbarlar uchun va do‘stlar uchun yozilgan hujjat turlicha bo‘lishi kerak.</p>\n<h4>Auditoriyaga moslash nimani anglatadi</h4>\n<ul><li><b>Til va uslub:</b> yosh bolalarga sodda so‘zlar, rasmiy hujjatda esa rasmiy uslub.</li><li><b>Shrift:</b> kichik yoshdagilar uchun yirikroq va o‘qilishi oson shrift.</li><li><b>Rasmlar:</b> bolalar hujjatida ko‘proq va yorqin tasvirlar, rasmiy hujjatda esa kamroq.</li><li><b>Ranglar:</b> o‘qishga xalaqit bermaydigan mos ranglar.</li></ul>\n<div class=\"ex\"><b>Misol.</b> Maktab e’lonini 1-sinf o‘quvchilari uchun tayyorlasak, yirik shrift, yorqin rasm va qisqa jumlalar ishlatamiz. Ota-onalar uchun xat esa rasmiy va aniq yoziladi.</div>\n<h4>Eslab qoling</h4><ul><li>Hujjat yaratishdan oldin kim o‘qishini aniqlang.</li><li>Auditoriyaga mos bo‘lmagan hujjat tushunarsiz bo‘lishi mumkin.</li></ul>","quiz":[{"q":"Auditoriya nima?","o":["Hujjatni o‘qiydigan yoki ko‘radigan kishilar","Fayl nomi","Hujjat yozilgan dastur","Printer turi"],"a":0,"e":"Auditoriya — hujjat mo‘ljallangan o‘quvchilar doirasi."},{"q":"Kichik yoshdagi bolalar uchun hujjat qanday bo‘lgani ma’qul?","o":["Yirik shrift, yorqin rasmlar, sodda jumlalar","Rasmsiz va rangsiz","Mayda shrift va murakkab atamalar","Faqat uzun matn"],"a":0,"e":"Bolalar uchun sodda va ko‘rgazmali hujjat tushunarliroq."},{"q":"Rasmiy xat qanday uslubda yoziladi?","o":["Hazil va maqollar bilan","Qisqartma so‘zlar bilan","Faqat rasmlar bilan","Rasmiy va aniq"],"a":3,"e":"Rasmiy xatda aniq va odobli uslub qo‘llanadi."},{"q":"Hujjat tayyorlashdan oldin birinchi navbatda nimani aniqlash kerak?","o":["Kim o‘qishini","Qaysi rangdagi sichqoncha borligini","Kompyuter markasini","Fayl hajmini"],"a":0,"e":"Auditoriyani bilgach, mazmun va ko‘rinish tanlanadi."},{"q":"Mayda va o‘qish qiyin shrift kimlar uchun noqulay?","o":["Hech kim uchun","Kichik yoshdagilar va keksalar uchun","Faqat kompyuter uchun","Faqat printer uchun"],"a":1,"e":"O‘qilishi qiyin shrift ko‘pchilik uchun noqulay."},{"q":"Auditoriyaga moslashtirishga nimalar kiradi?","o":["Til, shrift, rasm va ranglarni tanlash","Faqat dastur turini tanlash","Faqat sahifa raqami","Faqat fayl nomini tanlash"],"a":0,"e":"Bularning hammasi o‘quvchiga qulay qilib tanlanadi."},{"q":"Tadbirga taklifnoma yaratayotgan o‘quvchi nimani hisobga olishi kerak?","o":["Hech narsani","Taklif etilganlar kim ekanini","Faqat o‘z sevimli rangini","Faqat klaviatura turini"],"a":1,"e":"Taklifnoma mehmonlarga mos tuzilishi kerak."},{"q":"Matn ranglarini tanlashda nimaga e’tibor beriladi?","o":["Matn fonda yaxshi ko‘rinishiga","Rangsiz qolishiga","Eng yorqin ranglar ishlatilishiga","Har so‘z boshqa rangda bo‘lishiga"],"a":0,"e":"Matn o‘qilishi uchun fon bilan kontrast kerak."},{"q":"Qaysi hujjat yirik shrift va ko‘p rasm talab qiladi?","o":["Hisobot jadvali","Shartnoma","Rasmiy ariza","Birinchi sinflar uchun ertak kitobi"],"a":3,"e":"Kichik bolalar kitobi ko‘rgazmali bo‘ladi."},{"q":"Auditoriyaga mos bo‘lmagan hujjat qanday oqibatga olib keladi?","o":["Fayl o‘chib ketadi","Hech qanday oqibati yo‘q","Kompyuter buziladi","Mazmuni tushunarsiz bo‘lishi mumkin"],"a":3,"e":"Noto‘g‘ri uslub axborotni yetkazishga xalaqit beradi."}]},{"t":"5-dars. Loyiha ishi. Amaliy mashg‘ulot","lesson":"<p><b>Loyiha ishi</b> — mustaqil tanlangan mavzu bo‘yicha reja asosida bajariladigan, natijasi aniq ish. Bu darsda hujjat yaratish bo‘yicha bilimlarni amalda qo‘llaymiz.</p>\n<h4>Loyiha bosqichlari</h4>\n<ol><li><b>Mavzu va maqsadni tanlash.</b></li><li><b>Reja tuzish:</b> nima, kim uchun, qancha vaqtda.</li><li><b>Material to‘plash:</b> matn va rasmlar.</li><li><b>Hujjatni yaratish va formatlash.</b></li><li><b>Tekshirish va tuzatish.</b></li><li><b>Taqdim etish.</b></li></ol>\n<div class=\"ex\"><b>Amaliy mashg‘ulot.</b> «Mening sevimli kasbim» nomli bir sahifali hujjat yarating: sarlavha, 4-5 jumlali matn, bitta tasvir va hoshiya bo‘lsin. Auditoriya sifatida sinfdoshlaringizni tanlang.</div>\n<h4>Eslab qoling</h4><ul><li>Loyiha reja asosida bajariladi.</li><li>Tayyor ishni taqdim etishdan oldin xatolarni tekshiring.</li></ul>","quiz":[{"q":"Loyiha ishi nima?","o":["Reja asosida bajariladigan va natijasi aniq ish","Faqat rasm chizish","Faqat tugmalarni bosish","Tasodifiy yozilgan matn"],"a":0,"e":"Loyiha maqsadli, rejalashtirilgan ish."},{"q":"Loyiha ishining birinchi bosqichi qaysi?","o":["Taqdim etish","Chop etish","Mavzu va maqsadni tanlash","Faylni o‘chirish"],"a":2,"e":"Avval nima qilinishi aniqlanadi."},{"q":"Reja tuzishda nimalar aniqlanadi?","o":["Nima, kim uchun va qancha vaqtda bajarilishi","Faqat rang","Faqat sichqoncha turi","Faqat fayl hajmi"],"a":0,"e":"Reja ishni tartibli bajarishga yordam beradi."},{"q":"Material to‘plash bosqichida nima qilinadi?","o":["Ish baholanadi","Hujjat yopiladi","Dastur o‘chiriladi","Matn va rasmlar jamlanadi"],"a":3,"e":"Hujjat uchun kerakli axborot yig‘iladi."},{"q":"Tayyor ishni taqdim etishdan oldin nima qilish kerak?","o":["Xatolarni tekshirib tuzatish","Shriftni eng mayda qilish","Faylni nomsiz qoldirish","Hammasini o‘chirish"],"a":0,"e":"Tekshirish sifatni oshiradi."},{"q":"Loyiha hujjati kim uchun mo‘ljallanganini nima uchun bilish kerak?","o":["Kompyuterni tezlatish uchun","Uslub va ko‘rinishni moslash uchun","Hech nima uchun","Fayl hajmini oshirish uchun"],"a":1,"e":"Auditoriyaga qarab hujjat tuziladi."},{"q":"«Mening sevimli kasbim» hujjatiga nimalar kiritiladi?","o":["Faqat bo‘sh sahifa","Faqat sichqoncha rasmi","Sarlavha, matn, tasvir va hoshiya","Faqat fayl nomi"],"a":2,"e":"Topshiriqda shu elementlar talab qilingan."},{"q":"Qaysi ketma-ketlik to‘g‘ri?","o":["Yaratish, reja, tekshirish, material","Reja, material, yaratish, tekshirish","Tekshirish, reja, material, yaratish","Taqdim, material, reja, yaratish"],"a":1,"e":"Ish rejadan boshlanib, tekshirish bilan yakunlanadi."},{"q":"Hujjatni formatlash nimani o‘z ichiga oladi?","o":["Faqat chop etishni","Shrift, tekislash va hoshiya kabi sozlamalarni","Faqat saqlashni","Faqat o‘chirishni"],"a":1,"e":"Formatlash hujjat ko‘rinishini sozlaydi."},{"q":"Loyiha ishini bajarishning foydasi nima?","o":["Dastur yozishni to‘xtatish","Hech qanday foydasi yo‘q","Olingan bilimlarni amalda qo‘llash","Bilimlarni unutish"],"a":2,"e":"Loyiha bilimni mustahkamlaydi."}]},{"t":"6-dars. Tasvirni import qilish","lesson":"<p>Hujjatni yanada ko‘rgazmali qilish uchun unga rasm qo‘shiladi. Tayyor tasvirni dasturga olib kirish <b>tasvirni import qilish</b> deyiladi.</p>\n<h4>Tasvir manbalari</h4>\n<ul><li><b>Fayldan:</b> kompyuterdagi yoki fleshkadagi rasm fayli tanlanadi.</li><li><b>Internetdan:</b> rasm saqlab olinadi, so‘ng fayl sifatida qo‘shiladi.</li><li><b>Almashish buferidan:</b> rasm nusxalanib, hujjatga qo‘yiladi (Paste).</li><li><b>Ekran suratidan:</b> ekran tasviri olinib, hujjatga joylanadi.</li></ul>\n<p>Rasm fayllari turli <b>formatlarda</b> bo‘ladi: JPG, PNG, GIF, BMP. Format fayl nomining oxiridagi kengaytmadan bilinadi, masalan, <i>rasm.jpg</i>.</p>\n<div class=\"ex\"><b>Amaliy qadamlar.</b><ol><li>Hujjatda tasvir qo‘yiladigan joyga kursorni qo‘ying.</li><li>Rasm qo‘shish (Insert Picture) buyrug‘ini tanlang.</li><li>Kerakli rasm faylini toping va tasdiqlang.</li><li>Rasm hujjatda paydo bo‘lgach, uning joyini tekshiring.</li></ol></div>\n<h4>Eslab qoling</h4><ul><li>Import — tashqaridagi tasvirni dasturga olib kirish.</li><li>Rasm kursor turgan joyga qo‘shiladi.</li><li>Internetdagi rasmlardan foydalanishda mualliflik huquqiga e’tibor bering.</li></ul>","quiz":[{"q":"Tasvirni import qilish nima?","o":["Rasmni chop etish","Yangi rasmni noldan chizish","Rasmni o‘chirib tashlash","Tayyor tasvirni dasturga olib kirish"],"a":3,"e":"Import tashqaridagi tasvirni dastur ichiga qo‘shishdir."},{"q":"Quyidagilardan qaysi biri rasm fayli formati?","o":["EXE","MP3","JPG","DOCX"],"a":2,"e":"JPG — keng tarqalgan rasm formati."},{"q":"Rasm hujjatning qayerida paydo bo‘ladi?","o":["Doim sahifa o‘rtasida","Kursor turgan joyda","Doim hujjat oxirida","Doim birinchi sahifa tepasida"],"a":1,"e":"Tasvir kursor turgan joyga qo‘yiladi."},{"q":"Fayl formatini qanday bilish mumkin?","o":["Fayl yaratilgan soatdan","Fayl nomi oxiridagi kengaytmadan","Fayl rangidan","Monitor o‘lchamidan"],"a":1,"e":"Kengaytma (.jpg, .png) format haqida xabar beradi."},{"q":"To‘g‘ri tartibni tanlang: 1) rasm faylini tanlash 2) kursorni qo‘yish 3) rasm qo‘shish buyrug‘i.","o":["1, 3, 2","2, 3, 1","3, 1, 2","1, 2, 3"],"a":1,"e":"Avval joy tanlanadi, so‘ng buyruq beriladi va fayl tanlanadi."},{"q":"Internetdagi rasmni hujjatga qo‘shishning to‘g‘ri yo‘li qaysi?","o":["Hujjatni internetga ulash","Rasmni saqlab olib, fayldan qo‘shish","Rasm nomini hujjatga yozib qo‘yish","Monitorni rasmga yo‘naltirish"],"a":1,"e":"Saqlangan rasm fayl sifatida import qilinadi."},{"q":"Almashish buferidagi rasmni hujjatga qo‘yish uchun qaysi amal bajariladi?","o":["Paste (Qo‘yish)","Undo (Bekor qilish)","Cut (Kesish)","Save (Saqlash)"],"a":0,"e":"Paste bufer mazmunini kursor joyiga qo‘yadi."},{"q":"Rasmlar PNG, JPG yoki GIF deb bo‘linishi nimaga bog‘liq?","o":["Fayl formatiga","Rasm mazmuniga","Klaviatura turiga","Monitor turiga"],"a":0,"e":"Bular tasvir fayllarining turli formatlaridir."},{"q":"Mulohaza to‘g‘rimi: internetdagi har qanday rasmni mualliflik huquqiga e’tibor bermay ishlatish mumkin.","o":["Noto‘g‘ri, mualliflik huquqiga rioya qilish kerak","To‘g‘ri, agar rasm kichik bo‘lsa","Noto‘g‘ri, faqat rangli rasmlar himoyalangan","To‘g‘ri, hammasi ruxsat etilgan"],"a":0,"e":"Rasmlarning muallifi bor, undan foydalanishda huquqlarni hurmat qilish lozim."},{"q":"Maktab bayrami uchun e’lon tayyorlayapsiz, rasm kompyuteringizda saqlangan. Nima qilasiz?","o":["Rasmni qo‘lda hujjatga yopishtiraman","Rasm nomini matn sifatida yozaman","Kompyuterni qayta yoqaman","Rasm qo‘shish buyrug‘i orqali fayldan import qilaman"],"a":3,"e":"Saqlangan rasm fayldan import qilinadi."}]},{"t":"7-dars. Ishning boshlang‘ich nusxalari.","lesson":"<p>Rasm yoki hujjat ustida ishlaganda asl ish <b>boshlang‘ich nusxa</b> sifatida saqlab qo‘yilishi kerak. Chunki tahrir vaqtida xatoga yo‘l qo‘yib, asl holatni yo‘qotib qo‘yish mumkin.</p>\n<h4>Nega nusxa kerak?</h4>\n<ul><li>Ish buzilsa, asl holatga qaytish mumkin bo‘ladi.</li><li>Bir rasmdan bir nechta variant tayyorlash mumkin.</li><li>Fayl tasodifan o‘chib ketsa, zaxira nusxa qutqaradi.</li></ul>\n<h4>Qanday saqlanadi?</h4>\n<p>Asl faylni tahrir qilishdan oldin uning nusxasi olinadi yoki <b>«Boshqa nom bilan saqlash»</b> (Save as) buyrug‘i bilan yangi nom beriladi. Masalan: <i>rasm_asl.png</i> va <i>rasm_tahrir.png</i>. Nomlar mazmunga mos va tushunarli bo‘lishi kerak.</p>\n<div class=\"ex\"><b>Amaliy qadamlar.</b><ol><li>Ishlamoqchi bo‘lgan rasm faylini toping.</li><li>Uning nusxasini boshqa papkada saqlang.</li><li>Nusxa ustida o‘zgartirishlar kiriting.</li><li>Natijani yangi nom bilan saqlang.</li></ol></div>\n<h4>Eslab qoling</h4><ul><li>Asl faylni o‘zgartirmasdan saqlab qo‘ying.</li><li>Tahrirni nusxada bajaring.</li><li>Fayllarga tushunarli nom bering.</li></ul>","quiz":[{"q":"Boshlang‘ich nusxa nima?","o":["Tahrirdan oldingi asl ish holati","Faylning o‘chirilgan qismi","Eng oxirgi tahrir qilingan variant","Chop etilgan varaq"],"a":0,"e":"Asl nusxa o‘zgartirilmagan holatdagi fayldir."},{"q":"Nima uchun asl nusxani saqlab qo‘yish kerak?","o":["Xato bo‘lsa, asl holatga qaytish uchun","Kompyuter tezroq ishlashi uchun","Rasm rangli bo‘lishi uchun","Fayl hajmi kamayishi uchun"],"a":0,"e":"Zaxira nusxa xatolarni tuzatishga imkon beradi."},{"q":"Faylni yangi nom bilan saqlash uchun qaysi buyruq ishlatiladi?","o":["Undo","Save as (Boshqa nom bilan saqlash)","Paste","Close"],"a":1,"e":"Save as faylning yangi nusxasini yaratadi."},{"q":"Qaysi fayl nomlari juftligi tushunarliroq?","o":["yangi.png va yangi.png","a.png va b.png","rasm_asl.png va rasm_tahrir.png","1.png va 2.png"],"a":2,"e":"Mazmunga mos nomlar fayllarni ajratishga yordam beradi."},{"q":"Mulohaza to‘g‘rimi: tahrirni asl fayl ustida bajarish eng xavfsiz yo‘l.","o":["To‘g‘ri, nusxa shart emas","Noto‘g‘ri, tahrir nusxada bajarilishi kerak","Noto‘g‘ri, tahrir umuman mumkin emas","To‘g‘ri, agar fayl kichik bo‘lsa"],"a":1,"e":"Asl fayl buzilib qolmasligi uchun nusxadan foydalaniladi."},{"q":"To‘g‘ri tartibni tanlang: 1) tahrir qilish 2) asl nusxani saqlash 3) natijani yangi nom bilan saqlash.","o":["3, 2, 1","2, 1, 3","1, 3, 2","1, 2, 3"],"a":1,"e":"Avval nusxa saqlanadi, keyin tahrir qilinadi va natija saqlanadi."},{"q":"Rasmni tahrir qilib, uni buzib qo‘ydingiz. Asl nusxa bo‘lmasa nima bo‘ladi?","o":["Rasm o‘zi tiklanadi","Kompyuter avtomatik tuzatadi","Hech narsa o‘zgarmaydi","Asl holatga qaytish qiyin yoki imkonsiz bo‘ladi"],"a":3,"e":"Nusxa bo‘lmasa, asl ko‘rinishni yo‘qotish mumkin."},{"q":"Zaxira nusxani qayerda saqlash ma’qul?","o":["Hech qayerda saqlamaslik","Boshqa papkada yoki boshqa qurilmada","Faqat ish stolidagi bitta fayl sifatida","Asl fayl ustiga yozib"],"a":1,"e":"Boshqa joydagi nusxa asl fayl bilan birga yo‘qolmaydi."},{"q":"Bir rasmdan ikki xil variant tayyorlash uchun nima qilinadi?","o":["Faqat bitta fayl ishlatiladi","Rasm ustiga ikki marta yoziladi","Asl nusxadan ikkita alohida fayl yaratiladi","Rasm o‘chirib qayta yuklanadi"],"a":2,"e":"Har variant alohida nom bilan alohida saqlanadi."},{"q":"Quyidagilardan qaysi biri nusxa olish bilan bog‘liq amal?","o":["Faylni boshqa papkaga nusxalash","Monitorni tozalash","Kompyuterni o‘chirish","Sichqonchani almashtirish"],"a":0,"e":"Nusxalash faylning aynan o‘zidan ikkinchisini yaratadi."}]},{"t":"8-dars. Tasvirlarni aylantirish, teskari o‘girish. Tasvirni o‘lchamlarini o‘zgartish","lesson":"<p>Rasm hujjatga qo‘shilgach, uni kerakli ko‘rinishga keltirish mumkin: <b>aylantirish</b>, <b>teskari o‘girish</b> va <b>o‘lchamini o‘zgartirish</b>.</p>\n<h4>Asosiy amallar</h4>\n<ul><li><b>Aylantirish (Rotate):</b> rasm soat mili yo‘nalishida yoki unga teskari burchakka buriladi, masalan, 90 gradusga.</li><li><b>Teskari o‘girish (Flip):</b> rasm ko‘zgudagi aksidek gorizontal yoki vertikal bo‘yicha almashtiriladi.</li><li><b>O‘lcham o‘zgartirish:</b> rasmni belgilab, chetidagi nuqtalarni sichqoncha bilan tortiladi.</li></ul>\n<p>Rasm proporsiyasi buzilmasligi uchun o‘lchamni <b>burchakdagi</b> nuqtalardan tortish ma’qul. Yon tomondagi nuqtalar rasmni faqat bir yo‘nalishda cho‘zadi.</p>\n<div class=\"ex\"><b>Amaliy qadamlar.</b><ol><li>Rasmni sichqoncha bilan bosib belgilang.</li><li>Uni 90 gradusga aylantiring.</li><li>Gorizontal bo‘yicha teskari o‘giring.</li><li>Burchak nuqtasidan tortib, o‘lchamini kichraytiring.</li></ol></div>\n<h4>Eslab qoling</h4><ul><li>Amalni bajarishdan oldin rasmni belgilash kerak.</li><li>Burchak nuqtalari proporsiyani saqlaydi.</li><li>Xato bo‘lsa, Undo tugmasi yordam beradi.</li></ul>","quiz":[{"q":"Rasmni burchakka burish qaysi amal?","o":["Aylantirish (Rotate)","Nusxalash","Saqlash","Teskari o‘girish (Flip)"],"a":0,"e":"Rotate rasmni berilgan burchakka buradi."},{"q":"Rasmni ko‘zgudagi aksidek almashtirish qaysi amal?","o":["Aylantirish (Rotate)","Teskari o‘girish (Flip)","Kesish (Cut)","Qo‘yish (Paste)"],"a":1,"e":"Flip rasmning akslantirilgan ko‘rinishini beradi."},{"q":"Rasm ustida amal bajarishdan oldin nima qilinadi?","o":["Hujjat yopiladi","Rasm o‘chiriladi","Rasm belgilanadi","Dastur o‘chiriladi"],"a":2,"e":"Belgilangan rasmgagina amal qo‘llanadi."},{"q":"Rasm proporsiyasi buzilmasligi uchun o‘lchamni qaysi nuqtadan tortish kerak?","o":["Faqat tepadagi nuqtadan","Yon tomondagi nuqtadan","Burchakdagi nuqtadan","Faqat pastdagi nuqtadan"],"a":2,"e":"Burchak nuqtalari kenglik va balandlikni birga o‘zgartiradi."},{"q":"Yon tomondagi nuqtani tortsangiz nima bo‘ladi?","o":["Rasm faqat bir yo‘nalishda cho‘ziladi","Rasm aylanadi","Rasm o‘chadi","Rasm nusxalanadi"],"a":0,"e":"Bu usul proporsiyani buzishi mumkin."},{"q":"Mulohaza to‘g‘rimi: Flip va Rotate bir xil amal.","o":["Noto‘g‘ri, ular turli amallar","To‘g‘ri, ikkalasi bir xil","To‘g‘ri, faqat 90 gradusda","Noto‘g‘ri, Flip faqat matnga tegishli"],"a":0,"e":"Rotate buradi, Flip esa aksini hosil qiladi."},{"q":"Rasm yon tomonga yotib qolgan. Uni to‘g‘rilash uchun nima qilinadi?","o":["Rasm o‘chiriladi","Rasm nusxalanadi","Rasm rangi o‘zgartiriladi","90 gradusga aylantiriladi"],"a":3,"e":"To‘g‘ri burchakka aylantirish rasmni tik holatga keltiradi."},{"q":"Rasmning kattaligini o‘zgartirish nima deyiladi?","o":["O‘lchamini o‘zgartirish","Import qilish","Saqlash","Chop etish"],"a":0,"e":"Kenglik va balandlik o‘zgarishi o‘lcham o‘zgartirish hisoblanadi."},{"q":"Noto‘g‘ri bajarilgan amalni qaytarish uchun nima ishlatiladi?","o":["Close","Undo (Bekor qilish)","Print","Insert"],"a":1,"e":"Undo oxirgi amalni bekor qiladi."},{"q":"Rasmni 90 gradusga aylantirish qaysi burchakni bildiradi?","o":["Uchdan bir aylana","Yarim aylana","To‘g‘ri burchak (chorak aylana)","To‘liq aylana"],"a":2,"e":"90 gradus to‘g‘ri burchakka teng, ya’ni aylananing choragi."}]},{"t":"9-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 1</b> quyidagi darslarni qamrab oladi:</p><ul><li>Matn qo‘shish, o‘zgartrish va ko‘chirish</li><li>Shrift turi, o‘lchami va rangini o‘zgartrish. Matnni tekislash</li><li>Hujjatga tasvir va hoshiya qo‘shish</li><li>Hujjatlarni auditoriya uchun moslash</li><li>Loyiha ishi. Amaliy mashg‘ulot</li><li>Tasvirni import qilish</li><li>Ishning boshlang‘ich nusxalari.</li><li>Tasvirlarni aylantirish, teskari o‘girish. Tasvirni o‘lchamlarini o‘zgartish</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Hujjat tayyorlashdan oldin birinchi navbatda nimani aniqlash kerak?","o":["Kim o‘qishini","Qaysi rangdagi sichqoncha borligini","Kompyuter markasini","Fayl hajmini"],"a":0,"e":"Auditoriyani bilgach, mazmun va ko‘rinish tanlanadi."},{"q":"Loyiha ishini bajarishning foydasi nima?","o":["Dastur yozishni to‘xtatish","Hech qanday foydasi yo‘q","Olingan bilimlarni amalda qo‘llash","Bilimlarni unutish"],"a":2,"e":"Loyiha bilimni mustahkamlaydi."},{"q":"Matn rangini o‘zgartirish nimani o‘zgartiradi?","o":["Fayl nomini","Qog‘oz turini","Harflar rangini","Sahifa o‘lchamini"],"a":2,"e":"Shrift rangi harflar rangini belgilaydi."},{"q":"Matnni ko‘chirishdan oldin birinchi navbatda nima qilish kerak?","o":["Matnni belgilash","Shriftni o‘zgartirish","Dasturni yopish","Hujjatni saqlash"],"a":0,"e":"Avval kerakli matn belgilanadi, so‘ng Cut yoki Copy bajariladi."},{"q":"Almashish buferidagi rasmni hujjatga qo‘yish uchun qaysi amal bajariladi?","o":["Paste (Qo‘yish)","Undo (Bekor qilish)","Cut (Kesish)","Save (Saqlash)"],"a":0,"e":"Paste bufer mazmunini kursor joyiga qo‘yadi."},{"q":"Mulohaza to‘g‘rimi: Flip va Rotate bir xil amal.","o":["Noto‘g‘ri, ular turli amallar","To‘g‘ri, ikkalasi bir xil","To‘g‘ri, faqat 90 gradusda","Noto‘g‘ri, Flip faqat matnga tegishli"],"a":0,"e":"Rotate buradi, Flip esa aksini hosil qiladi."},{"q":"Boshlang‘ich nusxa nima?","o":["Tahrirdan oldingi asl ish holati","Faylning o‘chirilgan qismi","Eng oxirgi tahrir qilingan variant","Chop etilgan varaq"],"a":0,"e":"Asl nusxa o‘zgartirilmagan holatdagi fayldir."},{"q":"Tasvir hujjatning kerakli joyiga tushishi uchun qanday ish qilinadi?","o":["Dastur qayta yoqiladi","Avval hujjat chop etiladi","Avval kursor shu joyga qo‘yiladi","Hoshiya o‘chiriladi"],"a":2,"e":"Tasvir kursor turgan joyga qo‘shiladi."},{"q":"Noto‘g‘ri bajarilgan amalni bekor qilish uchun nima ishlatiladi?","o":["Undo (Bekor qilish)","Print","Paste","Save as"],"a":0,"e":"Undo oxirgi bajarilgan amalni qaytaradi."},{"q":"Tayyor ishni taqdim etishdan oldin nima qilish kerak?","o":["Xatolarni tekshirib tuzatish","Shriftni eng mayda qilish","Faylni nomsiz qoldirish","Hammasini o‘chirish"],"a":0,"e":"Tekshirish sifatni oshiradi."},{"q":"Harflar kattaligi nima deyiladi?","o":["Abzas","Shrift o‘lchami","Shrift turi","Tekislash"],"a":1,"e":"Harf kattaligi shrift o‘lchami bilan beriladi."},{"q":"Matn ranglarini tanlashda nimaga e’tibor beriladi?","o":["Matn fonda yaxshi ko‘rinishiga","Rangsiz qolishiga","Eng yorqin ranglar ishlatilishiga","Har so‘z boshqa rangda bo‘lishiga"],"a":0,"e":"Matn o‘qilishi uchun fon bilan kontrast kerak."},{"q":"Hujjatga tasvir qo‘shish uchun qaysi buyruq ishlatiladi?","o":["Insert (Qo‘yish) bo‘limidagi Picture","Spelling","Undo","Print"],"a":0,"e":"Tasvir Insert bo‘limidagi Picture yordamida qo‘shiladi."},{"q":"Reja tuzishda nimalar aniqlanadi?","o":["Nima, kim uchun va qancha vaqtda bajarilishi","Faqat rang","Faqat sichqoncha turi","Faqat fayl hajmi"],"a":0,"e":"Reja ishni tartibli bajarishga yordam beradi."},{"q":"Quyidagilardan qaysi biri nusxa olish bilan bog‘liq amal?","o":["Faylni boshqa papkaga nusxalash","Monitorni tozalash","Kompyuterni o‘chirish","Sichqonchani almashtirish"],"a":0,"e":"Nusxalash faylning aynan o‘zidan ikkinchisini yaratadi."},{"q":"«Mening maktabim» hujjati uchun eng mos tasvir qaysi?","o":["Bo‘sh oq kvadrat","Boshqa shahar xaritasi","Tasodifiy mashina rasmi","Maktab binosi rasmi"],"a":3,"e":"Tasvir hujjat mavzusiga mos bo‘lishi kerak."},{"q":"Qaysi hujjat yirik shrift va ko‘p rasm talab qiladi?","o":["Hisobot jadvali","Shartnoma","Rasmiy ariza","Birinchi sinflar uchun ertak kitobi"],"a":3,"e":"Kichik bolalar kitobi ko‘rgazmali bo‘ladi."},{"q":"Rasmning kattaligini o‘zgartirish nima deyiladi?","o":["O‘lchamini o‘zgartirish","Import qilish","Saqlash","Chop etish"],"a":0,"e":"Kenglik va balandlik o‘zgarishi o‘lcham o‘zgartirish hisoblanadi."},{"q":"Faylni yangi nom bilan saqlash uchun qaysi buyruq ishlatiladi?","o":["Undo","Save as (Boshqa nom bilan saqlash)","Paste","Close"],"a":1,"e":"Save as faylning yangi nusxasini yaratadi."},{"q":"To‘g‘ri tartibni tanlang: 1) rasm faylini tanlash 2) kursorni qo‘yish 3) rasm qo‘shish buyrug‘i.","o":["1, 3, 2","2, 3, 1","3, 1, 2","1, 2, 3"],"a":1,"e":"Avval joy tanlanadi, so‘ng buyruq beriladi va fayl tanlanadi."}]},{"t":"10-dars. Elektron jadval tushunchasi. Ma‘lumotlarni elektron jadvalga kiritish","lesson":"<p><b>Elektron jadval</b> — ma’lumotlarni jadval ko‘rinishida kiritish, saqlash va hisoblash uchun dastur (masalan, Excel yoki Calc).</p>\n<h4>Asosiy tushunchalar</h4>\n<ul><li><b>Ustun</b> — vertikal qator, harflar bilan belgilanadi (A, B, C).</li><li><b>Satr</b> — gorizontal qator, raqamlar bilan belgilanadi (1, 2, 3).</li><li><b>Katak (yacheyka)</b> — ustun va satr kesishgan joy. Manzili harf va raqamdan iborat: <i>B3</i>.</li><li><b>Varaq</b> — jadval joylashgan ish maydoni.</li></ul>\n<h4>Ma’lumot kiritish</h4>\n<p>Kerakli katakni bosib, ma’lumot yoziladi va <b>Enter</b> tugmasi bosiladi. Katakka matn, son yoki sana kiritish mumkin. Matn odatda chapga, sonlar o‘ngga tekislanadi.</p>\n<div class=\"ex\"><b>Amaliy qadamlar.</b><ol><li>A1 katakka «Ism», B1 katakka «Baho» deb yozing.</li><li>A2 va B2 ga birinchi o‘quvchining ma’lumotlarini kiriting.</li><li>Yana ikki satrni to‘ldiring.</li></ol></div>\n<h4>Eslab qoling</h4><ul><li>Katak manzili: avval ustun harfi, keyin satr raqami.</li><li>Ma’lumot Enter bilan tasdiqlanadi.</li><li>Elektron jadval hisoblashni ham avtomatlashtiradi.</li></ul>","quiz":[{"q":"Elektron jadval nima uchun mo‘ljallangan?","o":["Faqat rasm chizish uchun","Ma’lumotlarni jadvalda kiritish, saqlash va hisoblash uchun","Faqat internetga ulanish uchun","Faqat musiqa tinglash uchun"],"a":1,"e":"Elektron jadval jadvalli ma’lumotlar va hisob-kitob bilan ishlaydi."},{"q":"Elektron jadvalda ustunlar nima bilan belgilanadi?","o":["Belgilar bilan","Ranglar bilan","Harflar bilan","Raqamlar bilan"],"a":2,"e":"Ustunlar A, B, C kabi harflar bilan nomlanadi."},{"q":"Satrlar nima bilan belgilanadi?","o":["Ranglar bilan","Raqamlar bilan","Rasmlar bilan","Harflar bilan"],"a":1,"e":"Satrlar 1, 2, 3 kabi raqamlanadi."},{"q":"Katak manzili qanday yoziladi?","o":["Faqat harf","Avval ustun harfi, keyin satr raqami","Faqat raqam","Avval satr raqami, keyin ustun harfi"],"a":1,"e":"Masalan, C4 — C ustun va 4-satr kesishgan katak."},{"q":"B3 manzilli katak qayerda joylashgan?","o":["B ustun va 3-satr kesishgan joyda","B ustunning oxirida","3 ustun va B satr kesishgan joyda","Birinchi satrda"],"a":0,"e":"B — ustun, 3 — satr."},{"q":"Kiritilgan ma’lumotni tasdiqlash uchun qaysi tugma bosiladi?","o":["Enter","Shift","Esc","Caps Lock"],"a":0,"e":"Enter kiritishni yakunlaydi."},{"q":"Quyidagilardan qaysi biri katakka kiritilishi mumkin?","o":["Faqat son","Matn, son va sana","Faqat rasm nomi","Faqat matn"],"a":1,"e":"Katakka turli turdagi ma’lumotlar kiritiladi."},{"q":"Ustun va satr kesishgan joy nima deyiladi?","o":["Kursor","Varaq","Katak (yacheyka)","Sarlavha"],"a":2,"e":"Katak jadvalning eng kichik birligi."},{"q":"Mulohaza to‘g‘rimi: elektron jadval faqat matn yozish uchun ishlatiladi.","o":["To‘g‘ri, hisoblash imkoni yo‘q","Noto‘g‘ri, u faqat rasm uchun","To‘g‘ri, faqat matn uchun","Noto‘g‘ri, u hisoblash uchun ham ishlatiladi"],"a":3,"e":"Jadval dasturlari formulalar bilan hisob-kitob qila oladi."},{"q":"Sinfdagi o‘quvchilar ro‘yxatini baholari bilan kiritmoqchisiz. Qaysi dastur mos?","o":["Arxivlash dasturi","Tovush yozish dasturi","Elektron jadval dasturi","Antivirus dasturi"],"a":2,"e":"Jadvalli ma’lumotlar uchun elektron jadval qulay."}]},{"t":"11-dars. Sodda formulalarni kiritishda katak manzilidan foydalanish. Formulalarni nusxalash","lesson":"<p>Elektron jadvalning asosiy afzalligi — <b>formulalar</b> yordamida hisoblash. Formula har doim <b>«=»</b> belgisi bilan boshlanadi.</p>\n<h4>Katak manzilidan foydalanish</h4>\n<p>Formulada sonlar o‘rniga katak manzillari yoziladi. Masalan, A1 va B1 kataklardagi sonlarni qo‘shish uchun C1 katakka <b>=A1+B1</b> yoziladi. Katakdagi son o‘zgarsa, natija ham avtomatik qayta hisoblanadi.</p>\n<ul><li>Qo‘shish — <b>+</b>, ayirish — <b>-</b>, ko‘paytirish — <b>*</b>, bo‘lish — <b>/</b>.</li><li>Formula yozilgan katakda natija ko‘rinadi, formulaning o‘zi formulalar satrida turadi.</li></ul>\n<h4>Formulani nusxalash</h4>\n<p>Bir xil hisobni ko‘p satrda bajarish uchun formula nusxalanadi. Katak burchagidagi to‘ldirish markerini pastga tortsangiz, formula nusxalanadi va manzillar avtomatik moslashadi: C1 dagi <i>=A1+B1</i> C2 da <i>=A2+B2</i> bo‘ladi.</p>\n<div class=\"ex\"><b>Amaliy qadamlar.</b><ol><li>A1 va B1 ga ikkita son yozing.</li><li>C1 ga <i>=A1*B1</i> kiriting.</li><li>Formulani C2 va C3 ga nusxalang.</li></ol></div>\n<h4>Eslab qoling</h4><ul><li>Formula «=» bilan boshlanadi.</li><li>Sonlar o‘rniga katak manzili yoziladi.</li><li>Nusxalashda manzillar moslashadi.</li></ul>","quiz":[{"q":"Formula qaysi belgi bilan boshlanadi?","o":["?","+","=","#"],"a":2,"e":"Elektron jadvalda formula teng belgisi bilan boshlanadi."},{"q":"Elektron jadvalda ko‘paytirish qaysi belgi bilan yoziladi?","o":["*","x","/","+"],"a":0,"e":"Ko‘paytirish yulduzcha belgisi bilan bajariladi."},{"q":"Bo‘lish amali qaysi belgi bilan yoziladi?","o":["=","/","-","*"],"a":1,"e":"Bo‘lish uchun qiya chiziq ishlatiladi."},{"q":"A1 va B1 dagi sonlar yig‘indisini C1 da hisoblash formulasi qaysi?","o":["A1+B1","=A1B1","=A1+B1","C1=A1"],"a":2,"e":"Formula «=» dan boshlanadi va manzillar «+» bilan bog‘lanadi."},{"q":"Formulada katak manzili ishlatishning afzalligi nima?","o":["Natija har doim 0 chiqadi","Jadval rangli bo‘ladi","Formula qisqa bo‘ladi, xolos","Son o‘zgarsa, natija avtomatik yangilanadi"],"a":3,"e":"Manzil orqali hisoblash natijani avtomatik qayta hisoblaydi."},{"q":"C1 dagi =A1+B1 formulasi C2 ga nusxalansa, qanday bo‘ladi?","o":["=A1+B1","=C1+C2","=A2+B2","=A3+B3"],"a":2,"e":"Nusxalashda manzillar bir satr pastga suriladi."},{"q":"Katakda formula yozilgan bo‘lsa, katakning o‘zida nima ko‘rinadi?","o":["Hisoblash natijasi","Formulaning o‘zi","Bo‘sh joy","Katak manzili"],"a":0,"e":"Formula matni formulalar satrida, natija katakda ko‘rinadi."},{"q":"Mulohaza to‘g‘rimi: formulani har bir satr uchun qayta yozish shart.","o":["To‘g‘ri, aks holda xato chiqadi","Noto‘g‘ri, formula faqat bir marta ishlaydi","Noto‘g‘ri, uni nusxalash mumkin","To‘g‘ri, nusxalab bo‘lmaydi"],"a":2,"e":"Formula to‘ldirish markeri bilan nusxalanadi."},{"q":"A2 katakdagi son 5 edi, uni 8 ga o‘zgartirdingiz. A2 ga bog‘liq formula natijasi nima bo‘ladi?","o":["O‘chib ketadi","Avtomatik qayta hisoblanadi","Xato xabari chiqadi","O‘zgarmay qoladi"],"a":1,"e":"Formulalar manzildagi o‘zgarishni darhol hisobga oladi."},{"q":"Do‘kondagi mahsulot narxi va soni bor. Umumiy summani hisoblash uchun qaysi amal kerak?","o":["Ayirish","Ko‘paytirish","Bo‘lish","Hech qaysi"],"a":1,"e":"Summa = narx ko‘paytirilsa son."}]},{"t":"12-dars. Grafik yaratish.","lesson":"<p>Raqamlar jadvalda yozilganda ularni taqqoslash qiyin bo‘lishi mumkin. <b>Grafik</b> (diagramma) ma’lumotlarni rasm ko‘rinishida ko‘rsatib, tushunishni osonlashtiradi.</p>\n<h4>Diagramma turlari</h4>\n<ul><li><b>Ustunli:</b> qiymatlarni ustunlar balandligi orqali taqqoslaydi.</li><li><b>Chiziqli:</b> o‘zgarish dinamikasini (masalan, oylar bo‘yicha) ko‘rsatadi.</li><li><b>Doiraviy:</b> butunning qismlarini ko‘rsatadi.</li></ul>\n<h4>Grafik yaratish tartibi</h4>\n<p>Avval jadvaldagi kerakli ma’lumotlar (sarlavhalari bilan) belgilanadi. So‘ng diagramma qo‘shish buyrug‘i tanlanadi va tur belgilanadi. Natijada grafik hosil bo‘ladi. Unga <b>sarlavha</b> berish va o‘qlarni nomlash tavsiya etiladi.</p>\n<p>Jadvaldagi son o‘zgarsa, grafik ham o‘zgaradi, chunki u jadval bilan bog‘langan.</p>\n<div class=\"ex\"><b>Amaliy qadamlar.</b><ol><li>Jadvalga 5 ta fan va baholarni kiriting.</li><li>Ma’lumotlarni belgilang.</li><li>Ustunli diagramma yarating.</li><li>Grafikka sarlavha bering.</li></ol></div>\n<h4>Eslab qoling</h4><ul><li>Grafik oldin ma’lumotlarni belgilashni talab qiladi.</li><li>Tur ma’lumot maqsadiga qarab tanlanadi.</li><li>Sarlavha grafikni tushunarli qiladi.</li></ul>","quiz":[{"q":"Grafik (diagramma) nima uchun kerak?","o":["Faylni arxivlash uchun","Ma’lumotlarni ko‘rgazmali ko‘rsatish uchun","Matnni tekislash uchun","Jadvalni o‘chirish uchun"],"a":1,"e":"Diagramma raqamlarni tushunarli ko‘rinishga keltiradi."},{"q":"Qiymatlarni ustunlar balandligi orqali taqqoslaydigan diagramma qaysi?","o":["Doiraviy diagramma","Ustunli diagramma","Chiziqli diagramma","Nuqtali diagramma"],"a":1,"e":"Ustunli diagrammada qiymat ustun balandligi bilan ifodalanadi."},{"q":"Butunning qismlarini ko‘rsatish uchun qaysi diagramma qulay?","o":["Chiziqli","Ustunli","Doiraviy","Hech qaysi"],"a":2,"e":"Doiraviy diagramma ulushlarni ko‘rsatadi."},{"q":"Oylar bo‘yicha o‘zgarishni ko‘rsatish uchun qaysi diagramma mos?","o":["Rasmli","Doiraviy","Matnli","Chiziqli"],"a":3,"e":"Chiziqli grafik vaqt bo‘yicha o‘zgarishni yaxshi ko‘rsatadi."},{"q":"Grafik yaratishda birinchi qadam nima?","o":["Dasturni o‘chirish","Faylni yopish","Jadvaldagi ma’lumotlarni belgilash","Rasm qo‘shish"],"a":2,"e":"Grafik belgilangan ma’lumotlardan quriladi."},{"q":"To‘g‘ri tartibni tanlang: 1) tur tanlash 2) ma’lumotlarni belgilash 3) sarlavha berish.","o":["1, 2, 3","3, 1, 2","2, 1, 3","2, 3, 1"],"a":2,"e":"Avval ma’lumot, keyin tur, so‘ng sarlavha."},{"q":"Jadvaldagi son o‘zgarsa, grafik nima bo‘ladi?","o":["Rangi o‘zgaradi","O‘chib ketadi","Mos ravishda o‘zgaradi","O‘zgarmaydi"],"a":2,"e":"Grafik jadval ma’lumotlariga bog‘langan."},{"q":"Grafikka sarlavha berishning ahamiyati nima?","o":["Nima haqida ekanini tushuntiradi","Faylni kichraytiradi","Hech qanday ahamiyati yo‘q","Ma’lumotlarni o‘zgartiradi"],"a":0,"e":"Sarlavha grafik mavzusini ko‘rsatadi."},{"q":"Mulohaza to‘g‘rimi: grafik faqat bitta turda bo‘ladi.","o":["Noto‘g‘ri, grafik umuman turlarga bo‘linmaydi","Noto‘g‘ri, bir nechta turi bor","To‘g‘ri, faqat doiraviy","To‘g‘ri, faqat ustunli"],"a":1,"e":"Ustunli, chiziqli, doiraviy va boshqa turlar mavjud."},{"q":"Sinfdagi har bir o‘quvchining bo‘yini taqqoslamoqchisiz. Qaysi diagramma qulay?","o":["Ustunli diagramma","Doiraviy diagramma faqat bitta qiymat uchun","Hech qanday diagramma kerak emas","Faqat matnli xabar"],"a":0,"e":"Alohida qiymatlarni taqqoslash uchun ustunlar qulay."}]},{"t":"13-dars. Amaliy mashg‘ulot","lesson":"<p>Bu mashg‘ulotda elektron jadvalda o‘rganilgan barcha ko‘nikmalar birlashtiriladi: ma’lumot kiritish, formula yozish, nusxalash va grafik yaratish.</p>\n<h4>Vazifa: «Oilaviy xarajatlar» jadvali</h4>\n<div class=\"ex\"><ol><li>A1:D1 kataklarga sarlavhalarni yozing: «Mahsulot», «Narxi», «Soni», «Summa».</li><li>Kamida 5 ta mahsulot nomi, narxi va sonini kiriting.</li><li>D2 katakka <i>=B2*C2</i> formulasini yozing.</li><li>Formulani D6 gacha nusxalang.</li><li>Pastda umumiy summani hisoblang.</li><li>Mahsulot nomlari va summalar bo‘yicha ustunli diagramma yarating.</li><li>Faylni tushunarli nom bilan saqlang.</li></ol></div>\n<h4>Nazorat savollari</h4>\n<ul><li>Formula qaysi belgi bilan boshlanadi?</li><li>Nusxalashda manzillar qanday o‘zgaradi?</li><li>Diagramma uchun qaysi ma’lumotlar belgilanadi?</li></ul>\n<h4>Eslab qoling</h4><ul><li>Jadvalni sarlavhalar bilan to‘ldiring.</li><li>Takroriy hisob uchun formulani nusxalang.</li><li>Ishni oxirida saqlashni unutmang.</li></ul>","quiz":[{"q":"Formulani qaysi belgi bilan boshlash kerak?","o":["=","&","$","@"],"a":0,"e":"Barcha formulalar teng belgisidan boshlanadi."},{"q":"Narx B2 da, soni C2 da. Summa formulasi qaysi?","o":["=B2*C2","B2*C2","=B2+C2","=B2/C2"],"a":0,"e":"Summa narx va sonning ko‘paytmasi, formula «=» bilan boshlanadi."},{"q":"D2 dagi =B2*C2 formulasi D3 ga nusxalansa, qanday bo‘ladi?","o":["=B3*C3","=D2*D3","=B2*C2","=B4*C4"],"a":0,"e":"Nusxada manzillar bir satr pastga suriladi."},{"q":"Formulani ko‘p qatorga tez tarqatish uchun nima qilinadi?","o":["Hujjat qayta ochiladi","Katak o‘chiriladi","Har bir formula qo‘lda qayta yoziladi","To‘ldirish markeri pastga tortiladi"],"a":3,"e":"Marker formulani nusxalaydi."},{"q":"Diagramma yaratishda nimalarni belgilash kerak?","o":["Faqat bitta bo‘sh katakni","Butun kompyuter xotirasini","Hech narsani","Nomlar va summalar ustunlarini"],"a":3,"e":"Grafik belgilangan ma’lumotlardan quriladi."},{"q":"To‘g‘ri tartibni tanlang: 1) formula yozish 2) ma’lumot kiritish 3) diagramma yaratish.","o":["1, 2, 3","2, 1, 3","2, 3, 1","3, 2, 1"],"a":1,"e":"Avval ma’lumot, keyin hisob, oxirida diagramma."},{"q":"Umumiy summani qo‘shish uchun qaysi amal ishlatiladi?","o":["Ayirish","Ko‘paytirish","Qo‘shish","Bo‘lish"],"a":2,"e":"Summalar jamlanadi, ya’ni qo‘shiladi."},{"q":"Mulohaza to‘g‘rimi: ma’lumotni kiritganingizdan keyin jadvalni saqlash shart emas.","o":["Noto‘g‘ri, ishni saqlash kerak","Noto‘g‘ri, faqat formula saqlanadi","To‘g‘ri, faqat grafik saqlanadi","To‘g‘ri, o‘zi saqlanadi"],"a":0,"e":"Saqlanmagan ish yo‘qolishi mumkin."},{"q":"Narxi o‘zgardi. Summa nima bo‘ladi?","o":["Faylni qayta yaratish kerak bo‘ladi","Katak o‘chadi","Formula orqali avtomatik o‘zgaradi","O‘zgarmaydi"],"a":2,"e":"Manzillarga asoslangan formula natijani yangilaydi."},{"q":"Jadval ustunlariga sarlavha yozishning foydasi nima?","o":["Ma’lumot mazmuni tushunarli bo‘ladi","Hech qanday foydasi yo‘q","Fayl tezroq saqlanadi","Formula ishlaydi"],"a":0,"e":"Sarlavhalar ustun nimani bildirishini ko‘rsatadi."}]},{"t":"14-dars. Ma‘lumotlar turlari va bazasi, maydonlarni aniqlash","lesson":"<p><b>Ma’lumotlar bazasi</b> — bir-biri bilan bog‘liq ma’lumotlarning tartibli to‘plami. Masalan, maktab kutubxonasidagi kitoblar ro‘yxati yoki sinf jurnali.</p>\n<h4>Asosiy tushunchalar</h4>\n<ul><li><b>Jadval:</b> ma’lumotlar saqlanadigan asosiy tuzilma.</li><li><b>Yozuv (qator):</b> bitta obyekt haqidagi ma’lumot, masalan, bitta kitob.</li><li><b>Maydon (ustun):</b> obyektning bitta xususiyati, masalan, «Muallif».</li></ul>\n<h4>Ma’lumotlar turlari</h4>\n<p>Har bir maydon ma’lum turdagi ma’lumot saqlaydi:</p>\n<ul><li><b>Matn</b> — ism, nom;</li><li><b>Son</b> — yosh, narx;</li><li><b>Sana</b> — tug‘ilgan kun;</li><li><b>Mantiqiy (Ha/Yo‘q)</b> — ikki qiymatdan biri.</li></ul>\n<p>Maydon turi to‘g‘ri tanlansa, ma’lumot xatosiz kiritiladi va qidirish osonlashadi.</p>\n<div class=\"ex\"><b>Amaliy topshiriq.</b> «O‘quvchilar» bazasi uchun maydonlarni aniqlang: Ism (matn), Sinf (son), Tug‘ilgan sana (sana), A’lochi (Ha/Yo‘q).</div>\n<h4>Eslab qoling</h4><ul><li>Qator — yozuv, ustun — maydon.</li><li>Har maydonga mos tur beriladi.</li><li>Baza ma’lumotni tartibli saqlaydi.</li></ul>","quiz":[{"q":"Ma’lumotlar bazasi nima?","o":["Kompyuter qismi","Faqat rasmlar to‘plami","Dasturlash tili","O‘zaro bog‘liq ma’lumotlarning tartibli to‘plami"],"a":3,"e":"Baza ma’lumotlarni tartibli saqlaydi."},{"q":"Bazadagi bitta obyekt haqidagi ma’lumot nima deyiladi?","o":["Yozuv","Sarlavha","Varaq","Maydon"],"a":0,"e":"Yozuv jadvalning bitta qatoriga mos keladi."},{"q":"Obyektning bitta xususiyatini saqlaydigan ustun nima deyiladi?","o":["Katak manzili","Yozuv","Maydon","Diagramma"],"a":2,"e":"Maydon — ustun, masalan, «Muallif»."},{"q":"Tug‘ilgan kun uchun qaysi ma’lumot turi mos?","o":["Sana","Rasm","Mantiqiy","Ovoz"],"a":0,"e":"Sanalar uchun sana turi qo‘llanadi."},{"q":"«Ha» yoki «Yo‘q» qiymati saqlanadigan maydon turi qaysi?","o":["Sana","Son","Mantiqiy","Matn"],"a":2,"e":"Ikki qiymatdan biri mantiqiy turga mos."},{"q":"Kitob narxi maydoniga qaysi tur mos?","o":["Son","Rasm","Sana","Mantiqiy"],"a":0,"e":"Narx hisoblanishi mumkin bo‘lgan son."},{"q":"Mulohaza to‘g‘rimi: bazadagi qator — maydon, ustun — yozuv.","o":["Noto‘g‘ri, qator — yozuv, ustun — maydon","To‘g‘ri, aynan shunday","Noto‘g‘ri, ikkalasi bir narsa","To‘g‘ri, faqat katta bazada"],"a":0,"e":"Yozuv — qator, maydon — ustun."},{"q":"Nima uchun maydon turini to‘g‘ri tanlash muhim?","o":["Ma’lumot xatosiz kiritiladi va qidirish oson bo‘ladi","Jadval rangli bo‘ladi","Kompyuter tez yonadi","Ahamiyati yo‘q"],"a":0,"e":"Tur noto‘g‘ri bo‘lsa, xatolar va qidiruv muammolari chiqadi."},{"q":"Quyidagilardan qaysi biri ma’lumotlar bazasiga misol?","o":["Monitor","Bo‘sh daftar","Klaviatura","Maktab kutubxonasi kitoblari ro‘yxati"],"a":3,"e":"Kitoblar ro‘yxati tartibli saqlangan ma’lumotlardir."},{"q":"Do‘stlar bazasida «Telefon raqami» maydoni bor. Bu maydonda nima saqlanadi?","o":["Do‘stlarning barcha ismlari","Jadval nomi","Yozuvlar soni","Har bir do‘stning raqami"],"a":3,"e":"Maydon har bir yozuvdagi bitta xususiyatni saqlaydi."}]},{"t":"15-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 2</b> quyidagi darslarni qamrab oladi:</p><ul><li>Elektron jadval tushunchasi. Ma‘lumotlarni elektron jadvalga kiritish</li><li>Sodda formulalarni kiritishda katak manzilidan foydalanish. Formulalarni nusxalash</li><li>Grafik yaratish.</li><li>Amaliy mashg‘ulot</li><li>Ma‘lumotlar turlari va bazasi, maydonlarni aniqlash</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Sinfdagi o‘quvchilar ro‘yxatini baholari bilan kiritmoqchisiz. Qaysi dastur mos?","o":["Arxivlash dasturi","Tovush yozish dasturi","Elektron jadval dasturi","Antivirus dasturi"],"a":2,"e":"Jadvalli ma’lumotlar uchun elektron jadval qulay."},{"q":"Jadval ustunlariga sarlavha yozishning foydasi nima?","o":["Ma’lumot mazmuni tushunarli bo‘ladi","Hech qanday foydasi yo‘q","Fayl tezroq saqlanadi","Formula ishlaydi"],"a":0,"e":"Sarlavhalar ustun nimani bildirishini ko‘rsatadi."},{"q":"Elektron jadval nima uchun mo‘ljallangan?","o":["Faqat rasm chizish uchun","Ma’lumotlarni jadvalda kiritish, saqlash va hisoblash uchun","Faqat internetga ulanish uchun","Faqat musiqa tinglash uchun"],"a":1,"e":"Elektron jadval jadvalli ma’lumotlar va hisob-kitob bilan ishlaydi."},{"q":"C1 dagi =A1+B1 formulasi C2 ga nusxalansa, qanday bo‘ladi?","o":["=A1+B1","=C1+C2","=A2+B2","=A3+B3"],"a":2,"e":"Nusxalashda manzillar bir satr pastga suriladi."},{"q":"Ustun va satr kesishgan joy nima deyiladi?","o":["Kursor","Varaq","Katak (yacheyka)","Sarlavha"],"a":2,"e":"Katak jadvalning eng kichik birligi."},{"q":"Jadvaldagi son o‘zgarsa, grafik nima bo‘ladi?","o":["Rangi o‘zgaradi","O‘chib ketadi","Mos ravishda o‘zgaradi","O‘zgarmaydi"],"a":2,"e":"Grafik jadval ma’lumotlariga bog‘langan."},{"q":"Kiritilgan ma’lumotni tasdiqlash uchun qaysi tugma bosiladi?","o":["Enter","Shift","Esc","Caps Lock"],"a":0,"e":"Enter kiritishni yakunlaydi."},{"q":"Narxi o‘zgardi. Summa nima bo‘ladi?","o":["Faylni qayta yaratish kerak bo‘ladi","Katak o‘chadi","Formula orqali avtomatik o‘zgaradi","O‘zgarmaydi"],"a":2,"e":"Manzillarga asoslangan formula natijani yangilaydi."},{"q":"Diagramma yaratishda nimalarni belgilash kerak?","o":["Faqat bitta bo‘sh katakni","Butun kompyuter xotirasini","Hech narsani","Nomlar va summalar ustunlarini"],"a":3,"e":"Grafik belgilangan ma’lumotlardan quriladi."},{"q":"Butunning qismlarini ko‘rsatish uchun qaysi diagramma qulay?","o":["Chiziqli","Ustunli","Doiraviy","Hech qaysi"],"a":2,"e":"Doiraviy diagramma ulushlarni ko‘rsatadi."},{"q":"Mulohaza to‘g‘rimi: grafik faqat bitta turda bo‘ladi.","o":["Noto‘g‘ri, grafik umuman turlarga bo‘linmaydi","Noto‘g‘ri, bir nechta turi bor","To‘g‘ri, faqat doiraviy","To‘g‘ri, faqat ustunli"],"a":1,"e":"Ustunli, chiziqli, doiraviy va boshqa turlar mavjud."},{"q":"Katakda formula yozilgan bo‘lsa, katakning o‘zida nima ko‘rinadi?","o":["Hisoblash natijasi","Formulaning o‘zi","Bo‘sh joy","Katak manzili"],"a":0,"e":"Formula matni formulalar satrida, natija katakda ko‘rinadi."},{"q":"Kitob narxi maydoniga qaysi tur mos?","o":["Son","Rasm","Sana","Mantiqiy"],"a":0,"e":"Narx hisoblanishi mumkin bo‘lgan son."},{"q":"A1 va B1 dagi sonlar yig‘indisini C1 da hisoblash formulasi qaysi?","o":["A1+B1","=A1B1","=A1+B1","C1=A1"],"a":2,"e":"Formula «=» dan boshlanadi va manzillar «+» bilan bog‘lanadi."},{"q":"Formulada katak manzili ishlatishning afzalligi nima?","o":["Natija har doim 0 chiqadi","Jadval rangli bo‘ladi","Formula qisqa bo‘ladi, xolos","Son o‘zgarsa, natija avtomatik yangilanadi"],"a":3,"e":"Manzil orqali hisoblash natijani avtomatik qayta hisoblaydi."},{"q":"Bazadagi bitta obyekt haqidagi ma’lumot nima deyiladi?","o":["Yozuv","Sarlavha","Varaq","Maydon"],"a":0,"e":"Yozuv jadvalning bitta qatoriga mos keladi."},{"q":"Ma’lumotlar bazasi nima?","o":["Kompyuter qismi","Faqat rasmlar to‘plami","Dasturlash tili","O‘zaro bog‘liq ma’lumotlarning tartibli to‘plami"],"a":3,"e":"Baza ma’lumotlarni tartibli saqlaydi."},{"q":"Sinfdagi har bir o‘quvchining bo‘yini taqqoslamoqchisiz. Qaysi diagramma qulay?","o":["Ustunli diagramma","Doiraviy diagramma faqat bitta qiymat uchun","Hech qanday diagramma kerak emas","Faqat matnli xabar"],"a":0,"e":"Alohida qiymatlarni taqqoslash uchun ustunlar qulay."},{"q":"Nima uchun maydon turini to‘g‘ri tanlash muhim?","o":["Ma’lumot xatosiz kiritiladi va qidirish oson bo‘ladi","Jadval rangli bo‘ladi","Kompyuter tez yonadi","Ahamiyati yo‘q"],"a":0,"e":"Tur noto‘g‘ri bo‘lsa, xatolar va qidiruv muammolari chiqadi."},{"q":"Mulohaza to‘g‘rimi: ma’lumotni kiritganingizdan keyin jadvalni saqlash shart emas.","o":["Noto‘g‘ri, ishni saqlash kerak","Noto‘g‘ri, faqat formula saqlanadi","To‘g‘ri, faqat grafik saqlanadi","To‘g‘ri, o‘zi saqlanadi"],"a":0,"e":"Saqlanmagan ish yo‘qolishi mumkin."}]},{"t":"16-dars. Ma‘lumotlar bazasidan harakatlanish va teng sharti bilan query yaratish. Query-ma‘lumotlar bazasidan aniq ma‘lumotni qidirish uskunasi","lesson":"<p>Ma’lumotlar bazasi katta bo‘lsa, kerakli ma’lumotni qo‘lda izlash qiyin. Buning uchun <b>query (so‘rov)</b> — bazadan aniq ma’lumotni qidirish uskunasi ishlatiladi.</p>\n<h4>Bazada harakatlanish</h4>\n<ul><li>Yozuvlar orasida o‘tish: keyingi, oldingi, birinchi va oxirgi yozuvga o‘tish tugmalari.</li><li>Kerakli yozuv raqamini kiritib, unga to‘g‘ridan-to‘g‘ri o‘tish mumkin.</li></ul>\n<h4>Teng sharti bilan query</h4>\n<p>Query yaratishda maydon va shart belgilanadi. <b>Teng sharti</b> maydon qiymati berilgan qiymatga aynan teng yozuvlarni topadi. Masalan, «Sinf» maydoni 6 ga teng bo‘lgan barcha o‘quvchilarni topish. Natijada faqat shartga mos yozuvlar ko‘rsatiladi, qolganlari yashiriladi.</p>\n<div class=\"ex\"><b>Amaliy qadamlar.</b><ol><li>Yangi query yaratishni tanlang.</li><li>Kerakli jadval va maydonlarni belgilang.</li><li>«Sinf» maydoniga shart sifatida 6 ni kiriting.</li><li>Query ni ishga tushirib, natijani ko‘ring.</li></ol></div>\n<h4>Eslab qoling</h4><ul><li>Query — bazadan aniq ma’lumotni qidirish vositasi.</li><li>Teng sharti aynan mos qiymatni topadi.</li><li>Query asl ma’lumotni o‘chirmaydi.</li></ul>","quiz":[{"q":"Query nima?","o":["Matn yozish usuli","Bazadan aniq ma’lumotni qidirish uskunasi","Rasm tahrirlash dasturi","Jadvalni o‘chirish vositasi"],"a":1,"e":"Query ma’lumotlarni shart bo‘yicha qidiradi."},{"q":"Teng sharti nimani topadi?","o":["Bo‘sh maydonlarni","Maydon qiymati berilgan qiymatga aynan teng yozuvlarni","Eng katta qiymatni","Barcha yozuvlarni"],"a":1,"e":"Teng sharti aniq mos keluvchi yozuvlarni tanlaydi."},{"q":"«Sinf = 6» sharti qanday yozuvlarni ko‘rsatadi?","o":["Sinfi 6 bo‘lmaganlarni","Sinfi 6 dan katta o‘quvchilarni","Barcha o‘quvchilarni","Sinfi 6 bo‘lgan o‘quvchilarni"],"a":3,"e":"Teng sharti faqat aynan 6 ni topadi."},{"q":"Query natijasida shartga mos kelmagan yozuvlar nima bo‘ladi?","o":["Bazadan o‘chib ketadi","Boshqa jadvalga ko‘chadi","Rangi o‘zgaradi","Natijada ko‘rsatilmaydi"],"a":3,"e":"Query faqat ko‘rinishni tanlaydi, ma’lumotni o‘chirmaydi."},{"q":"Query yaratishda nima belgilanadi?","o":["Maydon va shart","Printer turi","Faqat fayl nomi","Monitor o‘lchami"],"a":0,"e":"Qidiruv maydon va shart bo‘yicha amalga oshiriladi."},{"q":"Yozuvlar orasida harakatlanish uchun nima ishlatiladi?","o":["Faqat klaviaturadagi Space","Faylni o‘chirish","Dasturni yopish","Keyingi, oldingi, birinchi, oxirgi yozuvga o‘tish tugmalari"],"a":3,"e":"Navigatsiya tugmalari yozuvlar bo‘ylab yuradi."},{"q":"Mulohaza to‘g‘rimi: query bazadagi ma’lumotlarni o‘chirib yuboradi.","o":["Noto‘g‘ri, u yangi baza yaratadi","To‘g‘ri, nomuvofiqlarini o‘chiradi","Noto‘g‘ri, u faqat qidiradi va ko‘rsatadi","To‘g‘ri, faqat birinchi yozuvni"],"a":2,"e":"Query asl ma’lumotni o‘zgartirmaydi."},{"q":"Bazada 500 ta kitob bor. Muallifi «Navoiy» bo‘lganlarni topish uchun nima qulay?","o":["Kompyuterni almashtirish","Hammasini birma-bir o‘qish","Muallif maydoniga teng sharti bilan query yaratish","Bazani o‘chirib qayta yozish"],"a":2,"e":"Query tez va aniq qidiradi."},{"q":"To‘g‘ri tartibni tanlang: 1) shart kiritish 2) natijani ko‘rish 3) query yaratishni boshlash.","o":["1, 2, 3","3, 1, 2","2, 3, 1","3, 2, 1"],"a":1,"e":"Avval query ochiladi, shart beriladi, keyin natija ko‘riladi."},{"q":"Qaysi holda teng sharti yozuvni topadi?","o":["Maydon bo‘sh bo‘lsa","Maydon qiymati shartdagi qiymat bilan aynan bir xil bo‘lsa","Har doim","Qiymat shartdan kichik bo‘lsa"],"a":1,"e":"Teng sharti aniq moslikni talab qiladi."}]},{"t":"17-dars. Takrorlash algoritmi","lesson":"<p><b>Takrorlash</b> quyidagi darslarni qamrab oladi:</p><ul><li>Ma‘lumotlar bazasidan harakatlanish va teng sharti bilan query yaratish. Query-ma‘lumotlar bazasidan aniq ma‘lumotni qidirish uskunasi</li></ul><p>Test <b>10 ta aralash savoldan</b> iborat. Qiynalgan mavzuingizning darsini qayta o‘qib chiqing.</p>","quiz":[{"q":"Yozuvlar orasida harakatlanish uchun nima ishlatiladi?","o":["Faqat klaviaturadagi Space","Faylni o‘chirish","Dasturni yopish","Keyingi, oldingi, birinchi, oxirgi yozuvga o‘tish tugmalari"],"a":3,"e":"Navigatsiya tugmalari yozuvlar bo‘ylab yuradi."},{"q":"Mulohaza to‘g‘rimi: query bazadagi ma’lumotlarni o‘chirib yuboradi.","o":["Noto‘g‘ri, u yangi baza yaratadi","To‘g‘ri, nomuvofiqlarini o‘chiradi","Noto‘g‘ri, u faqat qidiradi va ko‘rsatadi","To‘g‘ri, faqat birinchi yozuvni"],"a":2,"e":"Query asl ma’lumotni o‘zgartirmaydi."},{"q":"Teng sharti nimani topadi?","o":["Bo‘sh maydonlarni","Maydon qiymati berilgan qiymatga aynan teng yozuvlarni","Eng katta qiymatni","Barcha yozuvlarni"],"a":1,"e":"Teng sharti aniq mos keluvchi yozuvlarni tanlaydi."},{"q":"Bazada 500 ta kitob bor. Muallifi «Navoiy» bo‘lganlarni topish uchun nima qulay?","o":["Kompyuterni almashtirish","Hammasini birma-bir o‘qish","Muallif maydoniga teng sharti bilan query yaratish","Bazani o‘chirib qayta yozish"],"a":2,"e":"Query tez va aniq qidiradi."},{"q":"«Sinf = 6» sharti qanday yozuvlarni ko‘rsatadi?","o":["Sinfi 6 bo‘lmaganlarni","Sinfi 6 dan katta o‘quvchilarni","Barcha o‘quvchilarni","Sinfi 6 bo‘lgan o‘quvchilarni"],"a":3,"e":"Teng sharti faqat aynan 6 ni topadi."},{"q":"Query nima?","o":["Matn yozish usuli","Bazadan aniq ma’lumotni qidirish uskunasi","Rasm tahrirlash dasturi","Jadvalni o‘chirish vositasi"],"a":1,"e":"Query ma’lumotlarni shart bo‘yicha qidiradi."},{"q":"To‘g‘ri tartibni tanlang: 1) shart kiritish 2) natijani ko‘rish 3) query yaratishni boshlash.","o":["1, 2, 3","3, 1, 2","2, 3, 1","3, 2, 1"],"a":1,"e":"Avval query ochiladi, shart beriladi, keyin natija ko‘riladi."},{"q":"Query yaratishda nima belgilanadi?","o":["Maydon va shart","Printer turi","Faqat fayl nomi","Monitor o‘lchami"],"a":0,"e":"Qidiruv maydon va shart bo‘yicha amalga oshiriladi."},{"q":"Query natijasida shartga mos kelmagan yozuvlar nima bo‘ladi?","o":["Bazadan o‘chib ketadi","Boshqa jadvalga ko‘chadi","Rangi o‘zgaradi","Natijada ko‘rsatilmaydi"],"a":3,"e":"Query faqat ko‘rinishni tanlaydi, ma’lumotni o‘chirmaydi."},{"q":"Qaysi holda teng sharti yozuvni topadi?","o":["Maydon bo‘sh bo‘lsa","Maydon qiymati shartdagi qiymat bilan aynan bir xil bo‘lsa","Har doim","Qiymat shartdan kichik bo‘lsa"],"a":1,"e":"Teng sharti aniq moslikni talab qiladi."}]},{"t":"18-dars. Takrorlash algoritmidan foydalanib blok-sxemalar yaratish","lesson":"<p><b>Takrorlash</b> quyidagi darslarni qamrab oladi:</p><ul><li>Ma‘lumotlar bazasidan harakatlanish va teng sharti bilan query yaratish. Query-ma‘lumotlar bazasidan aniq ma‘lumotni qidirish uskunasi</li></ul><p>Test <b>10 ta aralash savoldan</b> iborat. Qiynalgan mavzuingizning darsini qayta o‘qib chiqing.</p>","quiz":[{"q":"To‘g‘ri tartibni tanlang: 1) shart kiritish 2) natijani ko‘rish 3) query yaratishni boshlash.","o":["1, 2, 3","3, 1, 2","2, 3, 1","3, 2, 1"],"a":1,"e":"Avval query ochiladi, shart beriladi, keyin natija ko‘riladi."},{"q":"Query natijasida shartga mos kelmagan yozuvlar nima bo‘ladi?","o":["Bazadan o‘chib ketadi","Boshqa jadvalga ko‘chadi","Rangi o‘zgaradi","Natijada ko‘rsatilmaydi"],"a":3,"e":"Query faqat ko‘rinishni tanlaydi, ma’lumotni o‘chirmaydi."},{"q":"«Sinf = 6» sharti qanday yozuvlarni ko‘rsatadi?","o":["Sinfi 6 bo‘lmaganlarni","Sinfi 6 dan katta o‘quvchilarni","Barcha o‘quvchilarni","Sinfi 6 bo‘lgan o‘quvchilarni"],"a":3,"e":"Teng sharti faqat aynan 6 ni topadi."},{"q":"Qaysi holda teng sharti yozuvni topadi?","o":["Maydon bo‘sh bo‘lsa","Maydon qiymati shartdagi qiymat bilan aynan bir xil bo‘lsa","Har doim","Qiymat shartdan kichik bo‘lsa"],"a":1,"e":"Teng sharti aniq moslikni talab qiladi."},{"q":"Query nima?","o":["Matn yozish usuli","Bazadan aniq ma’lumotni qidirish uskunasi","Rasm tahrirlash dasturi","Jadvalni o‘chirish vositasi"],"a":1,"e":"Query ma’lumotlarni shart bo‘yicha qidiradi."},{"q":"Teng sharti nimani topadi?","o":["Bo‘sh maydonlarni","Maydon qiymati berilgan qiymatga aynan teng yozuvlarni","Eng katta qiymatni","Barcha yozuvlarni"],"a":1,"e":"Teng sharti aniq mos keluvchi yozuvlarni tanlaydi."},{"q":"Mulohaza to‘g‘rimi: query bazadagi ma’lumotlarni o‘chirib yuboradi.","o":["Noto‘g‘ri, u yangi baza yaratadi","To‘g‘ri, nomuvofiqlarini o‘chiradi","Noto‘g‘ri, u faqat qidiradi va ko‘rsatadi","To‘g‘ri, faqat birinchi yozuvni"],"a":2,"e":"Query asl ma’lumotni o‘zgartirmaydi."},{"q":"Yozuvlar orasida harakatlanish uchun nima ishlatiladi?","o":["Faqat klaviaturadagi Space","Faylni o‘chirish","Dasturni yopish","Keyingi, oldingi, birinchi, oxirgi yozuvga o‘tish tugmalari"],"a":3,"e":"Navigatsiya tugmalari yozuvlar bo‘ylab yuradi."},{"q":"Query yaratishda nima belgilanadi?","o":["Maydon va shart","Printer turi","Faqat fayl nomi","Monitor o‘lchami"],"a":0,"e":"Qidiruv maydon va shart bo‘yicha amalga oshiriladi."},{"q":"Bazada 500 ta kitob bor. Muallifi «Navoiy» bo‘lganlarni topish uchun nima qulay?","o":["Kompyuterni almashtirish","Hammasini birma-bir o‘qish","Muallif maydoniga teng sharti bilan query yaratish","Bazani o‘chirib qayta yozish"],"a":2,"e":"Query tez va aniq qidiradi."}]},{"t":"19-dars. Scratch dasturida takrorlash amaliyotidan foydalanish","lesson":"<p><b>Scratch</b> — blokli dasturlash muhiti. Unda dastur buyruq bloklarini bir-biriga ulash orqali tuziladi. Takrorlash uchun <b>Control</b> (Boshqaruv) toifasidagi bloklar ishlatiladi.</p>\n<h4>Takrorlash bloklari</h4>\n<ul><li><b>repeat (takrorla)</b> — ichidagi buyruqlarni berilgan son marta bajaradi.</li>\n<li><b>forever (abadiy)</b> — ichidagi buyruqlarni to‘xtatilmaguncha cheksiz takrorlaydi.</li>\n<li><b>repeat until (…gacha takrorla)</b> — shart bajarilguncha takrorlaydi.</li></ul>\n<div class=\"ex\"><b>Amaliy misol.</b> Sprayt (qahramon) 10 marta qadam tashlasin:<ol><li>«When green flag clicked» blokini qo‘ying.</li><li>Uning tagiga «repeat» blokini ulang va sonni 10 qiling.</li><li>Ichiga «move 10 steps» va «wait» bloklarini joylashtiring.</li><li>Yashil bayroqni bosib ishga tushiring.</li></ol></div>\n<p>Takrorlashsiz 10 ta bir xil blok qo‘yish kerak bo‘lardi. «repeat» yordamida esa dastur qisqa bo‘ladi, sonni o‘zgartirish ham oson.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Takrorlash bloklari Control toifasida.</li><li>Bloklar C harfiga o‘xshash, ichiga buyruq joylanadi.</li><li>Forever blokidan keyin boshqa blok ulab bo‘lmaydi.</li></ul>","quiz":[{"q":"Scratchda takrorlash bloklari qaysi toifada joylashgan?","o":["Motion (Harakat)","Looks (Ko‘rinish)","Sound (Tovush)","Control (Boshqaruv)"],"a":3,"e":"Repeat, forever va repeat until Control toifasida bo‘ladi."},{"q":"«repeat 10» bloki nima qiladi?","o":["Ichidagi buyruqlarni 10 soniya kutadi","Dasturni 10 marta saqlaydi","Spraytni 10 qadam yuritadi","Ichidagi buyruqlarni 10 marta bajaradi"],"a":3,"e":"Repeat berilgan son marta takrorlaydi."},{"q":"«forever» bloki qanday ishlaydi?","o":["Buyruqlarni faqat bir marta bajaradi","Buyruqlarni 100 marta takrorlaydi","Dasturni darhol o‘chiradi","Ichidagi buyruqlarni to‘xtatilmaguncha cheksiz takrorlaydi"],"a":3,"e":"Forever — abadiy takrorlash bloki."},{"q":"Shart bajarilguncha takrorlash uchun qaysi blok mos?","o":["repeat 10","move 10 steps","say Hello","repeat until"],"a":3,"e":"Repeat until shart to‘g‘ri bo‘lguncha takrorlaydi."},{"q":"Sprayt 5 marta «move 10 steps» bajarsa, jami necha qadam yuradi?","o":["10 qadam","5 qadam","50 qadam","15 qadam"],"a":2,"e":"5 marta 10 qadam — 50 qadam."},{"q":"Dasturni boshlash uchun odatda qaysi blok ishlatiladi?","o":["forever","stop all","wait 1 seconds","When green flag clicked"],"a":3,"e":"Dastur yashil bayroq bosilganda boshlanishi uchun shu hodisa bloki qo‘yiladi."},{"q":"Takrorlash blokidan foydalanishning afzalligi qaysi?","o":["Dastur qisqa bo‘ladi va sonni osongina o‘zgartirish mumkin","Dastur albatta sekin ishlaydi","Sprayt yo‘qoladi","Bloklarni ulab bo‘lmaydi"],"a":0,"e":"Takrorlash bir xil bloklarni ko‘paytirmaslikka yordam beradi."},{"q":"Spraytni uzluksiz harakatlantirish kerak bo‘lsa, qaysi blokni tanlaysiz?","o":["stop this script","forever","hide","repeat 1"],"a":1,"e":"Forever uzluksiz takrorlashni ta’minlaydi."},{"q":"Takrorlash blokining shakli qanday?","o":["Faqat yumaloq","Faqat tekis chiziq","Uchburchak","Ichiga buyruqlar joylanadigan C harfiga o‘xshash"],"a":3,"e":"Takrorlash bloki ichiga boshqa bloklar qo‘yiladi."},{"q":"«repeat 4» ichida «move 20 steps» va «turn 90 degrees» turibdi. «move» necha marta bajariladi?","o":["8 marta","2 marta","90 marta","4 marta"],"a":3,"e":"Tana 4 marta bajariladi, har safar bitta move bor."}]},{"t":"20-dars. Scratch dasturida PEN uskunasidan foydalanish","lesson":"<p>Scratchda sprayt harakatlanganda iz qoldirishi, ya’ni chizishi mumkin. Buning uchun <b>Pen</b> (Qalam) kengaytmasi ishlatiladi. Uni Scratch oynasining pastki chap burchagidagi kengaytma qo‘shish tugmasi orqali ulaymiz.</p>\n<h4>Asosiy Pen bloklari</h4>\n<ul><li><b>pen down</b> — qalamni tushiradi: sprayt harakatlansa, chiziq chiziladi.</li>\n<li><b>pen up</b> — qalamni ko‘taradi: chizish to‘xtaydi.</li>\n<li><b>set pen color</b> — qalam rangini tanlaydi.</li>\n<li><b>set pen size</b> — chiziq yo‘g‘onligini belgilaydi.</li>\n<li><b>erase all</b> — sahnadagi barcha chizmalarni o‘chiradi.</li>\n<li><b>stamp</b> — spraytning tasviridan iz qoldiradi.</li></ul>\n<div class=\"ex\"><b>Amaliy misol: to‘g‘ri chiziq chizish.</b><ol><li>Pen kengaytmasini ulang.</li><li>«erase all» bilan sahnani tozalang.</li><li>«pen down» ni qo‘ying.</li><li>«move 100 steps» ni qo‘shing.</li><li>«pen up» bilan yakunlang.</li></ol></div>\n<p>Agar «pen down» bo‘lmasa, sprayt harakatlanadi, ammo chiziq chizilmaydi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Chizish uchun avval pen down kerak.</li><li>Pen up chizishni to‘xtatadi.</li><li>Erase all sahnani tozalaydi.</li></ul>","quiz":[{"q":"Scratchda chizish imkonini beruvchi kengaytma qaysi?","o":["Sensing","Pen","Video Sensing","Sound"],"a":1,"e":"Pen kengaytmasi sprayt harakati bilan chizish imkonini beradi."},{"q":"«pen down» bloki nima qiladi?","o":["Qalam rangini o‘zgartiradi","Sprayt tasvirini ko‘paytiradi","Qalamni tushiradi, sprayt harakatida chiziq chiziladi","Chizilgan hamma narsani o‘chiradi"],"a":2,"e":"Pen down — chizishni boshlash bloki."},{"q":"Chizishni to‘xtatish uchun qaysi blok ishlatiladi?","o":["stamp","pen up","erase all","pen down"],"a":1,"e":"Pen up qalamni ko‘taradi va iz qolmaydi."},{"q":"Sahnadagi barcha chizmalarni o‘chirish uchun qaysi blok kerak?","o":["pen up","stamp","erase all","set pen size"],"a":2,"e":"Erase all sahnani tozalaydi."},{"q":"Chiziq yo‘g‘onligini o‘zgartirish qaysi blok orqali bajariladi?","o":["move 10 steps","set pen color","pen up","set pen size"],"a":3,"e":"Set pen size qalam qalinligini belgilaydi."},{"q":"Quyidagi dasturda chiziq chiziladimi: «move 100 steps» (pen down yo‘q)?","o":["Yo‘q, chunki qalam tushirilmagan","Ha, faqat ikki marta","Ha, faqat qizil rangda","Ha, doim chiziladi"],"a":0,"e":"Pen down bo‘lmasa, sprayt iz qoldirmaydi."},{"q":"«stamp» bloki nima qiladi?","o":["Chiziq rangini o‘chiradi","Sprayt nomini o‘zgartiradi","Spraytning tasviridan sahnada iz qoldiradi","Dasturni to‘xtatadi"],"a":2,"e":"Stamp sprayt rasmini sahnaga muhrlaydi."},{"q":"Chizma tugagach, keyingi harakatda iz qolmasligi uchun nima qilinadi?","o":["pen up qo‘yiladi","erase all qo‘yiladi","stamp qo‘yiladi","forever qo‘yiladi"],"a":0,"e":"Pen up chizishni to‘xtatadi, chizma esa saqlanib qoladi."},{"q":"To‘g‘ri chiziq chizish buyruqlarining tartibi qaysi?","o":["pen down, move 100 steps, pen up","erase all, pen up, move","move 100 steps, pen up, pen down","pen up, pen down, erase all"],"a":0,"e":"Avval qalam tushiriladi, keyin harakatlanadi, so‘ng ko‘tariladi."},{"q":"Chiziq rangini qizilga o‘zgartirish uchun qaysi blokdan foydalaniladi?","o":["pen up","set pen size","set pen color","erase all"],"a":2,"e":"Set pen color qalam rangini belgilaydi."}]},{"t":"21-dars. Scratch dasturida shakllar bilan ishlash","lesson":"<p>Scratchda <b>Pen</b> kengaytmasi, <b>move</b> (yur) va <b>turn</b> (buril) bloklari yordamida geometrik shakllarni chizish mumkin. Sprayt «toshbaqa» kabi oldinga yuradi va kerakli burchakka buriladi.</p>\n<h4>Kvadrat chizish</h4>\n<p>Kvadratning 4 ta teng tomoni va 4 ta to‘g‘ri burchagi bor. Demak, spraytni oldinga yurgizib, 90 gradusga burish kerak.</p>\n<div class=\"ex\"><b>Qadamlar.</b><ol><li>«pen down» ni qo‘ying.</li><li>«move 100 steps» ni qo‘ying.</li><li>«turn 90 degrees» ni qo‘ying.</li><li>Shu ikki blokni yana 3 marta qaytaring (yoki «repeat 4» ichiga joylang).</li><li>«pen up» bilan tugating.</li></ol></div>\n<h4>Boshqa shakllar</h4>\n<ul><li><b>To‘g‘ri to‘rtburchak</b> — qarama-qarshi tomonlar teng, burchaklar 90 gradus.</li>\n<li><b>Teng tomonli uchburchak</b> — har safar 120 gradusga buriladi, 3 ta tomon chiziladi.</li></ul>\n<p>Sprayt shakl chizishni boshlagan nuqtaga qaytsa, shakl yopiladi. Tomon uzunligini «move» blokidagi son belgilaydi, burilish burchagini esa «turn» blokidagi son.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Kvadrat: 4 marta (yur, 90 gradusga bur).</li><li>Teng tomonli uchburchak: 3 marta (yur, 120 gradusga bur).</li><li>Chizishdan oldin pen down kerak.</li></ul>","quiz":[{"q":"Scratchda kvadrat chizish uchun spraytni har tomondan keyin necha gradusga burish kerak?","o":["90 gradusga","45 gradusga","60 gradusga","120 gradusga"],"a":0,"e":"Kvadratning burchaklari to‘g‘ri burchak, ya’ni 90 gradus."},{"q":"Kvadrat chizishda «move» va «turn» juftligi necha marta bajariladi?","o":["2 marta","360 marta","3 marta","4 marta"],"a":3,"e":"Kvadratning 4 ta tomoni bor."},{"q":"Teng tomonli uchburchak chizishda sprayt har safar necha gradusga buriladi?","o":["60 gradusga","120 gradusga","90 gradusga","180 gradusga"],"a":1,"e":"Uchburchakda tashqi burchak 120 gradus bo‘ladi."},{"q":"Shakl tomonining uzunligini qaysi blokdagi son belgilaydi?","o":["turn … degrees","move … steps","erase all","pen down"],"a":1,"e":"Move blokidagi qadam soni tomon uzunligini beradi."},{"q":"Chizma ko‘rinishi uchun qaysi blok albatta birinchi qo‘yilishi kerak (iz qolishi uchun)?","o":["stop all","erase all","pen up","pen down"],"a":3,"e":"Pen down bo‘lmasa, sprayt iz qoldirmaydi."},{"q":"«repeat 4: move 80, turn 90» dasturi qanday shakl chizadi?","o":["To‘g‘ri chiziq","Doira","Uchburchak","Tomoni 80 bo‘lgan kvadrat"],"a":3,"e":"4 teng tomon va to‘g‘ri burchaklar kvadratni beradi."},{"q":"Qaysi shaklda qarama-qarshi tomonlar teng, ammo qo‘shni tomonlar har xil bo‘lishi mumkin?","o":["Teng tomonli uchburchak","Kvadrat","Doira","To‘g‘ri to‘rtburchak"],"a":3,"e":"To‘g‘ri to‘rtburchakda faqat qarama-qarshi tomonlar teng bo‘ladi."},{"q":"Kvadrat chizilganda sprayt oxirida qayerga qaytadi?","o":["Boshlang‘ich nuqtaga","Yo‘qoladi","Sahnadan chiqib ketadi","Sahnaning markaziga"],"a":0,"e":"Shakl yopilishi uchun sprayt chizishni boshlagan nuqtaga qaytadi."},{"q":"Quyidagilardan qaysi tartib kvadratni to‘g‘ri chizadi?","o":["turn 90, pen up, move 100","pen up, move 100, erase all","pen down, repeat 4 (move 100, turn 90), pen up","repeat 3 (move 100, turn 120)"],"a":2,"e":"Qalam tushirilib, 4 marta yurish va 90 gradusga burilish bajariladi."},{"q":"Spraytni 120 gradusga burib 3 marta takrorlansa, qaysi shakl chiziladi?","o":["Kvadrat","Teng tomonli uchburchak","Oltiburchak","Beshburchak"],"a":1,"e":"Uchburchak: 3 tomon, har safar 120 gradus."}]},{"t":"22-dars. Scratch dasturida takrorlash bloki yordamida yangi shakl chizish","lesson":"<p>Takrorlash blokidan foydalanib, istalgan <b>muntazam ko‘pburchak</b> (barcha tomonlari va burchaklari teng) chizish mumkin. Buning uchun bitta formula bor: burilish burchagi = <b>360 ni tomonlar soniga bo‘lish</b>.</p>\n<h4>Burilish burchaklari</h4>\n<ul><li>Uchburchak (3 tomon): 360 : 3 = 120 gradus.</li>\n<li>Kvadrat (4 tomon): 360 : 4 = 90 gradus.</li>\n<li>Beshburchak (5 tomon): 360 : 5 = 72 gradus.</li>\n<li>Oltiburchak (6 tomon): 360 : 6 = 60 gradus.</li></ul>\n<div class=\"ex\"><b>Misol: oltiburchak chizish.</b><ol><li>«pen down» qo‘ying.</li><li>«repeat 6» blokini oling.</li><li>Ichiga «move 60 steps» va «turn 60 degrees» ni joylang.</li><li>Dasturni ishga tushiring.</li></ol></div>\n<h4>Aylanaga yaqin shakl</h4>\n<p>Agar «repeat 36» ichida «move 10 steps» va «turn 10 degrees» bo‘lsa, ko‘pburchak juda ko‘p tomonli bo‘lib, aylanaga o‘xshab ketadi. Bunda 36 ta burilish 360 gradus beradi.</p>\n<p>Tomonlar soni ko‘paygan sayin shakl silliqlashadi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Takrorlash soni = tomonlar soni.</li><li>Burchak = 360 ni tomonlar soniga bo‘lganda chiqadi.</li><li>To‘liq aylanish 360 gradus.</li></ul>","quiz":[{"q":"Muntazam beshburchak chizishda burilish burchagi qancha bo‘ladi?","o":["90 gradus","72 gradus","60 gradus","108 gradus"],"a":1,"e":"360 ni 5 ga bo‘lsak, 72 chiqadi."},{"q":"Muntazam oltiburchak uchun «repeat» ichida qaysi juftlik to‘g‘ri?","o":["repeat 5: move 50, turn 72","repeat 6: move 50, turn 60","repeat 4: move 50, turn 90","repeat 6: move 50, turn 120"],"a":1,"e":"6 tomon, burchak 360 : 6 = 60."},{"q":"Muntazam ko‘pburchakda burilish burchagini topish formulasi qaysi?","o":["180 ni tomonlar soniga ko‘paytirish","Tomonlar sonidan 90 ni ayirish","Tomon uzunligini 2 ga bo‘lish","360 ni tomonlar soniga bo‘lish"],"a":3,"e":"To‘liq aylanish 360 gradus, u tomonlar soniga teng bo‘linadi."},{"q":"«repeat 8» bilan muntazam sakkizburchak chizilsa, qancha burchakka burish kerak?","o":["45 gradus","60 gradus","30 gradus","90 gradus"],"a":0,"e":"360 : 8 = 45."},{"q":"«repeat 36: move 10, turn 10» qaysi shaklga eng yaqin?","o":["Aylana","Kvadrat","Uchburchak","To‘g‘ri chiziq"],"a":0,"e":"Tomonlar ko‘p va burilishlar kichik bo‘lgani uchun aylanaga o‘xshaydi."},{"q":"«repeat 36: move 10, turn 10» da sprayt jami necha gradusga buriladi?","o":["10 gradus","180 gradus","36 gradus","360 gradus"],"a":3,"e":"36 marta 10 gradus — 360 gradus."},{"q":"Beshburchak chizishda takrorlash soni nechta bo‘lishi kerak?","o":["3","72","6","5"],"a":3,"e":"Takrorlash soni tomonlar soniga teng."},{"q":"Sprayt kvadrat o‘rniga uchburchak chizishi uchun nimani o‘zgartirish kerak?","o":["Faqat qalam rangini o‘zgartirish","Faqat qalam yo‘g‘onligini o‘zgartirish","Takrorlash sonini 3 qilib, burchakni 120 gradus qilish","Pen down ni o‘chirish"],"a":2,"e":"Takrorlash soni va burilish burchagi shaklni belgilaydi."},{"q":"Tomonlar soni ortgan sari muntazam ko‘pburchak qanday o‘zgaradi?","o":["Uchburchakka aylanadi","To‘g‘ri chiziqqa aylanadi","Yo‘qoladi","Aylanaga yaqinlashib, silliqlashadi"],"a":3,"e":"Tomon ko‘paysa, burchaklar yumshab, shakl aylanaga yaqinlashadi."},{"q":"Muntazam ko‘pburchak deb qanday ko‘pburchakka aytiladi?","o":["Faqat tomonlari har xil ko‘pburchakka","Barcha tomonlari va burchaklari teng ko‘pburchakka","Faqat 4 tomonli shaklga","Burchaklari bo‘lmagan shaklga"],"a":1,"e":"Muntazam ko‘pburchakda tomonlar ham, burchaklar ham teng."}]},{"t":"23-dars. Takrorlash blokidan foydalanib dastur natijasini taxmin qilish","lesson":"<p><b>Takrorlash</b> quyidagi darslarni qamrab oladi:</p><ul><li>Ma‘lumotlar bazasidan harakatlanish va teng sharti bilan query yaratish. Query-ma‘lumotlar bazasidan aniq ma‘lumotni qidirish uskunasi</li><li>Scratch dasturida takrorlash amaliyotidan foydalanish</li><li>Scratch dasturida PEN uskunasidan foydalanish</li><li>Scratch dasturida shakllar bilan ishlash</li><li>Scratch dasturida takrorlash bloki yordamida yangi shakl chizish</li></ul><p>Test <b>10 ta aralash savoldan</b> iborat. Qiynalgan mavzuingizning darsini qayta o‘qib chiqing.</p>","quiz":[{"q":"Scratchda chizish imkonini beruvchi kengaytma qaysi?","o":["Sensing","Pen","Video Sensing","Sound"],"a":1,"e":"Pen kengaytmasi sprayt harakati bilan chizish imkonini beradi."},{"q":"«pen down» bloki nima qiladi?","o":["Qalam rangini o‘zgartiradi","Sprayt tasvirini ko‘paytiradi","Qalamni tushiradi, sprayt harakatida chiziq chiziladi","Chizilgan hamma narsani o‘chiradi"],"a":2,"e":"Pen down — chizishni boshlash bloki."},{"q":"Teng tomonli uchburchak chizishda sprayt har safar necha gradusga buriladi?","o":["60 gradusga","120 gradusga","90 gradusga","180 gradusga"],"a":1,"e":"Uchburchakda tashqi burchak 120 gradus bo‘ladi."},{"q":"Teng sharti nimani topadi?","o":["Bo‘sh maydonlarni","Maydon qiymati berilgan qiymatga aynan teng yozuvlarni","Eng katta qiymatni","Barcha yozuvlarni"],"a":1,"e":"Teng sharti aniq mos keluvchi yozuvlarni tanlaydi."},{"q":"Shart bajarilguncha takrorlash uchun qaysi blok mos?","o":["repeat 10","move 10 steps","say Hello","repeat until"],"a":3,"e":"Repeat until shart to‘g‘ri bo‘lguncha takrorlaydi."},{"q":"Beshburchak chizishda takrorlash soni nechta bo‘lishi kerak?","o":["3","72","6","5"],"a":3,"e":"Takrorlash soni tomonlar soniga teng."},{"q":"«repeat 36: move 10, turn 10» da sprayt jami necha gradusga buriladi?","o":["10 gradus","180 gradus","36 gradus","360 gradus"],"a":3,"e":"36 marta 10 gradus — 360 gradus."},{"q":"«Sinf = 6» sharti qanday yozuvlarni ko‘rsatadi?","o":["Sinfi 6 bo‘lmaganlarni","Sinfi 6 dan katta o‘quvchilarni","Barcha o‘quvchilarni","Sinfi 6 bo‘lgan o‘quvchilarni"],"a":3,"e":"Teng sharti faqat aynan 6 ni topadi."},{"q":"Scratchda takrorlash bloklari qaysi toifada joylashgan?","o":["Motion (Harakat)","Looks (Ko‘rinish)","Sound (Tovush)","Control (Boshqaruv)"],"a":3,"e":"Repeat, forever va repeat until Control toifasida bo‘ladi."},{"q":"Scratchda kvadrat chizish uchun spraytni har tomondan keyin necha gradusga burish kerak?","o":["90 gradusga","45 gradusga","60 gradusga","120 gradusga"],"a":0,"e":"Kvadratning burchaklari to‘g‘ri burchak, ya’ni 90 gradus."}]},{"t":"24-dars. Scratch dasturida protseduralar bilan ishlash","lesson":"<p>Katta dasturda bir xil buyruqlar guruhi bir necha joyda kerak bo‘lishi mumkin. Ularni har gal qayta yozmaslik uchun <b>protsedura</b> yaratiladi.</p>\n<p><b>Protsedura</b> — nom berilgan, alohida yozilgan va kerak bo‘lganda chaqiriladigan buyruqlar guruhi. Scratchda uni <b>«My Blocks» (Mening bloklarim)</b> toifasida «Make a Block» (Blok yaratish) orqali yaratamiz.</p>\n<h4>Protsedura yaratish</h4>\n<div class=\"ex\"><b>Misol: «kvadrat» protsedurasi.</b><ol><li>«My Blocks» toifasida blok yaratish tugmasini bosing.</li><li>Blokka «kvadrat» deb nom bering.</li><li>Paydo bo‘lgan «define kvadrat» blokining tagiga «repeat 4: move 50, turn 90» ni joylang.</li><li>Asosiy dasturda «kvadrat» blokini chaqiring.</li></ol></div>\n<h4>Afzalliklari</h4>\n<ul><li>Dastur qisqaradi va o‘qish osonlashadi.</li><li>Bir xil kodni qayta yozish shart emas.</li><li>Tuzatish kerak bo‘lsa, faqat bitta joyda o‘zgartiriladi.</li></ul>\n<p>Protsedura ichida o‘zgaruvchan qiymat (parametr) ham ishlatish mumkin, masalan, kvadrat tomoni uzunligi.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Protsedura — nomli buyruqlar guruhi.</li><li>Avval aniqlanadi (define), so‘ng chaqiriladi.</li><li>Bir marta yoziladi, ko‘p marta ishlatiladi.</li></ul>","quiz":[{"q":"Protsedura nima?","o":["Sahna rangi","Dastur muharriri","Nom berilgan va kerak bo‘lganda chaqiriladigan buyruqlar guruhi","Faqat bitta sprayt"],"a":2,"e":"Protsedura nomlangan buyruqlar to‘plamidir."},{"q":"Scratchda o‘z blokingizni yaratish qaysi toifada amalga oshiriladi?","o":["Events","Operators","My Blocks","Looks"],"a":2,"e":"Mening bloklarim toifasida yangi blok yaratiladi."},{"q":"Protsedura yaratishning asosiy afzalligi qaysi?","o":["Bir xil kodni qayta yozmasdan ko‘p marta ishlatish mumkin","Dastur albatta uzayadi","Sprayt ko‘payadi","Dastur ishlamay qoladi"],"a":0,"e":"Protsedura kodni takrorlashdan saqlaydi."},{"q":"Yaratilgan protsedura asosiy dasturda qanday ishga tushiriladi?","o":["Sprayt nomini o‘zgartirish bilan","Uning blokini asosiy dasturga qo‘yib chaqiriladi","Faqat kompyuterni o‘chirib yoqish bilan","Pen up bilan"],"a":1,"e":"Protsedura blokini skriptga qo‘yish uni chaqirish hisoblanadi."},{"q":"«define kvadrat» bloki nimani anglatadi?","o":["Rangni o‘zgartiradi","Kvadratni o‘chiradi","«kvadrat» protsedurasi nimadan iboratligini aniqlaydi","Dasturni to‘xtatadi"],"a":2,"e":"Define blokining tagida protsedura tanasi yoziladi."},{"q":"Protsedura ichidagi kodni o‘zgartirsak, nima bo‘ladi?","o":["Faqat birinchi chaqirilgan joyda o‘zgaradi","Dastur o‘chadi","Protsedura chaqirilgan hamma joyda yangi natija chiqadi","Hech narsa o‘zgarmaydi"],"a":2,"e":"Kod bitta joyda turgani uchun o‘zgarish hamma chaqiruvga ta’sir qiladi."},{"q":"Quyidagilardan qaysi tartib to‘g‘ri?","o":["Avval protsedurani aniqlash, so‘ng chaqirish","Faqat chaqirish","Avval chaqirish, hech qachon aniqlamaslik","Faqat o‘chirish"],"a":0,"e":"Chaqirilishi uchun protsedura oldin aniqlangan bo‘lishi kerak."},{"q":"Spraytga 3 ta kvadratni turli joylarda chizdirish kerak. Eng qulay yo‘l qaysi?","o":["Qalamni o‘chirish","«kvadrat» protsedurasini yaratib, 3 marta chaqirish","Kvadrat kodini 3 marta yozib chiqish","Faqat bitta kvadrat chizish"],"a":1,"e":"Protsedura qayta yozishni oldini oladi."},{"q":"Protsedura parametri nimaga xizmat qiladi?","o":["Protsedura ishini o‘zgaruvchan qiymat (masalan, o‘lcham) bilan boshqarishga","Dasturni o‘chirishga","Faylni nusxalashga","Ovozni balandlatishga"],"a":0,"e":"Parametr protseduraga tashqaridan qiymat beradi."},{"q":"Quyidagilardan qaysi biri protsedura ishlatish natijasi emas?","o":["Dastur albatta uzayadi va qiyinlashadi","Dastur o‘qishga qulay bo‘ladi","Dastur qisqaradi","Tuzatish osonlashadi"],"a":0,"e":"Protsedura dasturni qisqartiradi va soddalashtiradi."}]},{"t":"25-dars. Dekompozitsiyadan foydalanish. Kichik masala yechimi orqali katta masalaga o‘tish","lesson":"<p>Katta va murakkab masalani birdaniga yechish qiyin. Shuning uchun uni bir nechta kichik, sodda masalalarga bo‘lamiz. Bu usul <b>dekompozitsiya</b> deyiladi.</p>\n<p><b>Dekompozitsiya</b> — murakkab masalani kichik qismlarga ajratib, har birini alohida yechish va keyin natijalarni birlashtirish.</p>\n<h4>Bosqichlar</h4>\n<ol><li>Katta masalani aniqlash.</li><li>Uni kichik qismlarga ajratish.</li><li>Har bir qismni alohida yechish.</li><li>Qismlarni birlashtirib, to‘liq yechim olish.</li></ol>\n<div class=\"ex\"><b>Misol: Scratchda uy chizish.</b><br>Katta masala — uy chizish. Kichik masalalar: 1) kvadrat (devor) chizish; 2) uchburchak (tom) chizish; 3) to‘rtburchak (eshik) chizish. Har biri uchun alohida protsedura yoziladi, so‘ng asosiy dasturda ketma-ket chaqiriladi.</div>\n<h4>Hayotiy misol</h4>\n<p>Bayram dasturxonini tayyorlash: menyu tuzish, mahsulot sotib olish, pishirish, dasturxon yozish. Har bir qism alohida bajariladi.</p>\n<h4>Afzalliklari</h4>\n<ul><li>Masala tushunarli bo‘ladi.</li><li>Ishni bo‘lib bajarish mumkin.</li><li>Xatoni topish oson.</li></ul>\n<h4>Eslab qoling</h4>\n<ul><li>Dekompozitsiya — masalani qismlarga bo‘lish.</li><li>Kichik yechimlar katta yechimni beradi.</li></ul>","quiz":[{"q":"Dekompozitsiya nima?","o":["Masalani o‘chirib tashlash","Dasturni nusxalash","Murakkab masalani kichik qismlarga ajratib yechish","Faqat rasm chizish"],"a":2,"e":"Dekompozitsiya — masalani sodda qismlarga bo‘lish."},{"q":"Dekompozitsiyaning to‘g‘ri tartibi qaysi?","o":["Birlashtirish, aniqlash, o‘chirish","Masalani aniqlash, qismlarga bo‘lish, har birini yechish, birlashtirish","Faqat yechish","Bo‘lmasdan yechish, o‘chirish"],"a":1,"e":"Avval ajratib, keyin yechib va birlashtiriladi."},{"q":"Scratchda uy chizish masalasi qaysi kichik masalalarga bo‘linadi?","o":["Faqat sprayt nomi","Faqat ovoz","Devor (kvadrat), tom (uchburchak), eshik","Faqat qalam rangi"],"a":2,"e":"Uyni oddiy shakllar yig‘indisi sifatida chizish mumkin."},{"q":"Dekompozitsiyaning afzalligi qaysi?","o":["Masala yanada murakkablashadi","Dastur ishlamaydi","Masala tushunarli bo‘ladi va xatoni topish osonlashadi","Ishni bo‘lib bo‘lmaydi"],"a":2,"e":"Kichik qismlarda xatoni topish va tuzatish oson."},{"q":"Quyidagilardan qaysi biri dekompozitsiyaga misol?","o":["Faylni qayta nomlash","Bir sahifani o‘chirish","Kompyuterni yoqish","Maktab bayramini tayyorlashni vazifalarga bo‘lish"],"a":3,"e":"Bayram ishlari alohida vazifalarga bo‘linadi."},{"q":"Dekompozitsiyadan keyin eng oxirgi bosqich qaysi?","o":["Masalani tanlash","Hech narsa qilmaslik","Qism yechimlarni birlashtirish","Masalani qismlarga ajratish"],"a":2,"e":"Oxirida kichik yechimlar yig‘ilib, umumiy natija olinadi."},{"q":"Scratchda dekompozitsiya natijasini dasturda qanday ifodalash qulay?","o":["Har bir qism uchun alohida protsedura yozish","Hamma buyruqni bitta uzun qatorga yozish","Hamma spraytni o‘chirish","Faqat forever ishlatish"],"a":0,"e":"Qismlar protsedura sifatida yoziladi."},{"q":"Katta masalani kichik masalalarga bo‘lish nima uchun foydali?","o":["Masala yo‘qoladi","Har bir kichik masalani yechish osonroq","Dastur qisqarmaydi","Kompyuter tezlashadi"],"a":1,"e":"Sodda qismlarni yechish va tekshirish oson."},{"q":"To‘g‘ri mulohazani toping.","o":["Kichik masalalar hech qachon katta masalaga aloqador emas","Dekompozitsiya faqat matematikada ishlatiladi","Dekompozitsiyada masala bo‘linmaydi","Kichik masalalarning yechimi birlashib, katta masalaning yechimini beradi"],"a":3,"e":"Dekompozitsiya hayotning ko‘p sohalarida ishlatiladi."},{"q":"Ikki qavatli uyni chizish masalasini yechishda dekompozitsiya qanday qo‘llanadi?","o":["Hammasi bir buyruq bilan chiziladi","Bir qavat, tom va eshik kabi qismlarni alohida chizib, so‘ng birlashtiriladi","Hech qanday bo‘linish bo‘lmaydi","Faqat bitta kvadrat chiziladi"],"a":1,"e":"Murakkab rasm oddiy qismlardan tuziladi."}]},{"t":"26-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 3</b> quyidagi darslarni qamrab oladi:</p><ul><li>Ma‘lumotlar bazasidan harakatlanish va teng sharti bilan query yaratish. Query-ma‘lumotlar bazasidan aniq ma‘lumotni qidirish uskunasi</li><li>Scratch dasturida takrorlash amaliyotidan foydalanish</li><li>Scratch dasturida PEN uskunasidan foydalanish</li><li>Scratch dasturida shakllar bilan ishlash</li><li>Scratch dasturida takrorlash bloki yordamida yangi shakl chizish</li><li>Scratch dasturida protseduralar bilan ishlash</li><li>Dekompozitsiyadan foydalanish. Kichik masala yechimi orqali katta masalaga o‘tish</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Yaratilgan protsedura asosiy dasturda qanday ishga tushiriladi?","o":["Sprayt nomini o‘zgartirish bilan","Uning blokini asosiy dasturga qo‘yib chaqiriladi","Faqat kompyuterni o‘chirib yoqish bilan","Pen up bilan"],"a":1,"e":"Protsedura blokini skriptga qo‘yish uni chaqirish hisoblanadi."},{"q":"Scratchda uy chizish masalasi qaysi kichik masalalarga bo‘linadi?","o":["Faqat sprayt nomi","Faqat ovoz","Devor (kvadrat), tom (uchburchak), eshik","Faqat qalam rangi"],"a":2,"e":"Uyni oddiy shakllar yig‘indisi sifatida chizish mumkin."},{"q":"Kvadrat chizilganda sprayt oxirida qayerga qaytadi?","o":["Boshlang‘ich nuqtaga","Yo‘qoladi","Sahnadan chiqib ketadi","Sahnaning markaziga"],"a":0,"e":"Shakl yopilishi uchun sprayt chizishni boshlagan nuqtaga qaytadi."},{"q":"Quyidagilardan qaysi biri dekompozitsiyaga misol?","o":["Faylni qayta nomlash","Bir sahifani o‘chirish","Kompyuterni yoqish","Maktab bayramini tayyorlashni vazifalarga bo‘lish"],"a":3,"e":"Bayram ishlari alohida vazifalarga bo‘linadi."},{"q":"Teng sharti nimani topadi?","o":["Bo‘sh maydonlarni","Maydon qiymati berilgan qiymatga aynan teng yozuvlarni","Eng katta qiymatni","Barcha yozuvlarni"],"a":1,"e":"Teng sharti aniq mos keluvchi yozuvlarni tanlaydi."},{"q":"Protsedura ichidagi kodni o‘zgartirsak, nima bo‘ladi?","o":["Faqat birinchi chaqirilgan joyda o‘zgaradi","Dastur o‘chadi","Protsedura chaqirilgan hamma joyda yangi natija chiqadi","Hech narsa o‘zgarmaydi"],"a":2,"e":"Kod bitta joyda turgani uchun o‘zgarish hamma chaqiruvga ta’sir qiladi."},{"q":"«repeat 36: move 10, turn 10» da sprayt jami necha gradusga buriladi?","o":["10 gradus","180 gradus","36 gradus","360 gradus"],"a":3,"e":"36 marta 10 gradus — 360 gradus."},{"q":"Shart bajarilguncha takrorlash uchun qaysi blok mos?","o":["repeat 10","move 10 steps","say Hello","repeat until"],"a":3,"e":"Repeat until shart to‘g‘ri bo‘lguncha takrorlaydi."},{"q":"Muntazam oltiburchak uchun «repeat» ichida qaysi juftlik to‘g‘ri?","o":["repeat 5: move 50, turn 72","repeat 6: move 50, turn 60","repeat 4: move 50, turn 90","repeat 6: move 50, turn 120"],"a":1,"e":"6 tomon, burchak 360 : 6 = 60."},{"q":"Muntazam beshburchak chizishda burilish burchagi qancha bo‘ladi?","o":["90 gradus","72 gradus","60 gradus","108 gradus"],"a":1,"e":"360 ni 5 ga bo‘lsak, 72 chiqadi."},{"q":"Takrorlash blokidan foydalanishning afzalligi qaysi?","o":["Dastur qisqa bo‘ladi va sonni osongina o‘zgartirish mumkin","Dastur albatta sekin ishlaydi","Sprayt yo‘qoladi","Bloklarni ulab bo‘lmaydi"],"a":0,"e":"Takrorlash bir xil bloklarni ko‘paytirmaslikka yordam beradi."},{"q":"To‘g‘ri chiziq chizish buyruqlarining tartibi qaysi?","o":["pen down, move 100 steps, pen up","erase all, pen up, move","move 100 steps, pen up, pen down","pen up, pen down, erase all"],"a":0,"e":"Avval qalam tushiriladi, keyin harakatlanadi, so‘ng ko‘tariladi."},{"q":"Chiziq yo‘g‘onligini o‘zgartirish qaysi blok orqali bajariladi?","o":["move 10 steps","set pen color","pen up","set pen size"],"a":3,"e":"Set pen size qalam qalinligini belgilaydi."},{"q":"Chizma tugagach, keyingi harakatda iz qolmasligi uchun nima qilinadi?","o":["pen up qo‘yiladi","erase all qo‘yiladi","stamp qo‘yiladi","forever qo‘yiladi"],"a":0,"e":"Pen up chizishni to‘xtatadi, chizma esa saqlanib qoladi."},{"q":"Ikki qavatli uyni chizish masalasini yechishda dekompozitsiya qanday qo‘llanadi?","o":["Hammasi bir buyruq bilan chiziladi","Bir qavat, tom va eshik kabi qismlarni alohida chizib, so‘ng birlashtiriladi","Hech qanday bo‘linish bo‘lmaydi","Faqat bitta kvadrat chiziladi"],"a":1,"e":"Murakkab rasm oddiy qismlardan tuziladi."},{"q":"Quyidagilardan qaysi tartib kvadratni to‘g‘ri chizadi?","o":["turn 90, pen up, move 100","pen up, move 100, erase all","pen down, repeat 4 (move 100, turn 90), pen up","repeat 3 (move 100, turn 120)"],"a":2,"e":"Qalam tushirilib, 4 marta yurish va 90 gradusga burilish bajariladi."},{"q":"Scratchda kvadrat chizish uchun spraytni har tomondan keyin necha gradusga burish kerak?","o":["90 gradusga","45 gradusga","60 gradusga","120 gradusga"],"a":0,"e":"Kvadratning burchaklari to‘g‘ri burchak, ya’ni 90 gradus."},{"q":"Query natijasida shartga mos kelmagan yozuvlar nima bo‘ladi?","o":["Bazadan o‘chib ketadi","Boshqa jadvalga ko‘chadi","Rangi o‘zgaradi","Natijada ko‘rsatilmaydi"],"a":3,"e":"Query faqat ko‘rinishni tanlaydi, ma’lumotni o‘chirmaydi."},{"q":"«forever» bloki qanday ishlaydi?","o":["Buyruqlarni faqat bir marta bajaradi","Buyruqlarni 100 marta takrorlaydi","Dasturni darhol o‘chiradi","Ichidagi buyruqlarni to‘xtatilmaguncha cheksiz takrorlaydi"],"a":3,"e":"Forever — abadiy takrorlash bloki."},{"q":"Qaysi holda teng sharti yozuvni topadi?","o":["Maydon bo‘sh bo‘lsa","Maydon qiymati shartdagi qiymat bilan aynan bir xil bo‘lsa","Har doim","Qiymat shartdan kichik bo‘lsa"],"a":1,"e":"Teng sharti aniq moslikni talab qiladi."}]},{"t":"27-dars. Web manzillar haqida tushuncha. Qidirish tizimini ishlash tamoyili va axborotning ishonchliligi.","lesson":"<p>Internetdagi har bir web-sahifaning o‘z manzili bor. Bu manzil <b>URL</b> deb ataladi. Masalan: <i>https://www.example.uz/maqola</i>.</p>\n<h4>URL qismlari</h4>\n<ul><li><b>https</b> — ma’lumot uzatish protokoli (s harfi himoyalangan ulanishni bildiradi).</li>\n<li><b>www.example.uz</b> — sayt nomi, ya’ni <b>domen</b>. «.uz» — O‘zbekiston domeni.</li>\n<li><b>/maqola</b> — saytdagi aniq sahifa yo‘li.</li></ul>\n<h4>Qidirish tizimi qanday ishlaydi?</h4>\n<p>Qidirish tizimi (Google, Yandex, Bing kabi) maxsus dasturlar yordamida internetdagi sahifalarni doimiy ko‘rib chiqadi va ularni o‘z <b>indeksiga</b> (katta ma’lumotlar bazasiga) yozib oladi. Siz so‘z kiritganingizda, tizim indeksdan mos sahifalarni topib, ahamiyatlilik tartibida ro‘yxat qilib beradi.</p>\n<div class=\"ex\"><b>Maslahat.</b> Qidirishda aniq <b>kalit so‘zlar</b> yozing: «Amir Temur hayoti» «tarix» dan ko‘ra aniqroq natija beradi.</div>\n<h4>Axborotning ishonchliligi</h4>\n<p>Internetdagi hamma narsa to‘g‘ri emas. Tekshiring: manba kim? Muallif ko‘rsatilganmi? Sana yangimi? Boshqa saytlarda ham shunday yozilganmi?</p>\n<h4>Eslab qoling</h4>\n<ul><li>URL — sahifaning internetdagi manzili.</li><li>Qidiruv tizimi indeksdan natija beradi.</li><li>Axborotni kamida bir nechta manbada tekshiring.</li></ul>","quiz":[{"q":"URL nima?","o":["Brauzer turi","Elektron pochta paroli","Kompyuter nomi","Web-sahifaning internetdagi manzili"],"a":3,"e":"URL sahifani topish uchun ishlatiladigan manzil."},{"q":"URL manzilidagi «.uz» qismi nimani bildiradi?","o":["Rasm formatini","Matn fayl turini","Antivirus nomini","O‘zbekiston domenini"],"a":3,"e":"«.uz» — O‘zbekistonning milliy domeni."},{"q":"Quyidagilardan qaysi biri qidirish tizimi?","o":["Paint","Scratch","Google","Word"],"a":2,"e":"Google internetda qidirish tizimidir."},{"q":"Qidirish tizimi natijani qanday topadi?","o":["O‘z indeksidagi sahifalardan mosini tanlab beradi","Faqat kitobdan","Faqat televizordan","Kompyuteringizdagi fayllardan"],"a":0,"e":"Indeks — qidiruv tizimi yig‘gan sahifalar bazasi."},{"q":"Aniqroq natija olish uchun qidirish so‘rovini qanday yozish kerak?","o":["Bo‘sh qoldirib","Juda uzun tasodifiy matn bilan","Faqat bitta harf bilan","Aniq kalit so‘zlar bilan"],"a":3,"e":"Aniq kalit so‘zlar mos sahifalarni topishga yordam beradi."},{"q":"https manzilidagi «s» harfi nimani bildiradi?","o":["Surat borligini","Himoyalangan ulanishni","Sekin ishlashni","Saytning rangini"],"a":1,"e":"https — himoyalangan protokol."},{"q":"Qaysi holat axborot ishonchsiz bo‘lishi mumkinligini ko‘rsatadi?","o":["Sayt tanilgan ilmiy muassasaniki","Muallif ma’lum, manba rasmiy","Bir nechta manba bir xil gapiradi","Muallif va sana ko‘rsatilmagan"],"a":3,"e":"Manba noma’lum bo‘lsa, ishonchni tekshirish kerak."},{"q":"Internetda topilgan ma’lumotga ishonishdan oldin nima qilish kerak?","o":["Darhol o‘chirish","Hech narsa tekshirmaslik","Boshqa ishonchli manbalar bilan solishtirish","Darhol hammaga yuborish"],"a":2,"e":"Bir nechta manbada tasdiqlangan axborot ishonchliroq."},{"q":"«www.example.uz» qismi URL ning qaysi qismi?","o":["Fayl hajmi","Parol","Sahifa rangi","Domen (sayt nomi)"],"a":3,"e":"Domen — saytning nomi."},{"q":"Qidirish tizimi indeksi nima?","o":["Brauzer tugmasi","Kompyuter klaviaturasi","Internet sahifalari haqidagi katta ma’lumotlar bazasi","Elektron xat papkasi"],"a":2,"e":"Indeksda sahifalar haqida ma’lumot saqlanadi."}]},{"t":"28-dars. Axborotni filtrlash. Web-sahifa, web-sayt, URL manzilidagi matnlarni saqlash","lesson":"<p>Internetda ma’lumot juda ko‘p, shuning uchun keraklisini ajratib olish — <b>axborotni filtrlash</b> zarur.</p>\n<p><b>Filtrlash</b> — ko‘p ma’lumot orasidan maqsadga mos, ishonchli va foydali qismini tanlab olish, keraksizini chetga surish.</p>\n<h4>Qanday filtrlash mumkin?</h4>\n<ul><li>Aniq kalit so‘zlar yozish.</li><li>Qidiruv tizimidagi sozlamalardan foydalanish (masalan, sana yoki rasm/video turi bo‘yicha).</li><li>Ishonchli saytlarni tanlash, reklama va shubhali sahifalarni o‘tkazib yuborish.</li><li>Sarlavha va qisqa tavsifni o‘qib chiqib, keyin sahifani ochish.</li></ul>\n<h4>Topilgan axborotni saqlash</h4>\n<div class=\"ex\"><b>Amaliy usullar.</b><ol><li><b>Matnni nusxalash:</b> kerakli matnni belgilab, nusxa olib, hujjatga joylash. Manba manzilini ham yozib qo‘ying.</li><li><b>URL ni saqlash:</b> brauzer manzil qatoridan nusxa olib, hujjatga yozib qo‘yish.</li><li><b>Xatcho‘p:</b> sahifani brauzerning sevimli sahifalari ro‘yxatiga qo‘shish.</li><li><b>Sahifani fayl qilib saqlash:</b> brauzerning «saqlash» imkoniyati orqali.</li></ol></div>\n<p>Boshqa odamning matnini nusxalaganda manbani ko‘rsatish kerak.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Filtrlash keraksiz ma’lumotni olib tashlaydi.</li><li>URL va matnni saqlab, manbani yozib qo‘ying.</li></ul>","quiz":[{"q":"Axborotni filtrlash nima?","o":["Faqat rasm chizish","Ko‘p ma’lumotdan keraklisini tanlab olish","Kompyuterni tozalash","Barcha ma’lumotni o‘chirish"],"a":1,"e":"Filtrlash maqsadga mos axborotni ajratishdir."},{"q":"Qaysi usul filtrlashga yordam beradi?","o":["Aniq kalit so‘zlar bilan qidirish","Hech narsa o‘qimaslik","Har qanday sahifani ochib chiqish","Barcha reklamaga bosish"],"a":0,"e":"Aniq so‘rov natijani toraytiradi."},{"q":"Sahifaning URL manzilini saqlashdan maqsad nima?","o":["Rasmni kichraytirish","Keyinroq shu sahifaga qaytish va manbani ko‘rsatish","Parolni o‘zgartirish","Kompyuter tezligini oshirish"],"a":1,"e":"URL manba manzilini saqlash imkonini beradi."},{"q":"Internetdan olingan matnni hujjatga joylasangiz, nimani unutmaslik kerak?","o":["Matnni o‘z nomingizdan yozishni","Barcha so‘zlarni o‘zgartirib tashlashni","Manbani ko‘rsatishni","Manbani yashirishni"],"a":2,"e":"Boshqa muallif matnidan foydalanganda manba ko‘rsatiladi."},{"q":"Xatcho‘p nima?","o":["Antivirus dasturi","Brauzerda sahifani tez topish uchun belgilab qo‘yish","Elektron xat turi","Rasm formati"],"a":1,"e":"Xatcho‘p sevimli sahifaga tez qaytishga yordam beradi."},{"q":"Qaysi holda axborotni filtrlash noto‘g‘ri bajarilgan?","o":["Sana bo‘yicha yangi natijani tanlash","Bir nechta manbani solishtirish","Ishonchli saytni tanlash","Reklama sahifasidagi ma’lumotni tekshirmay haqiqat deb qabul qilish"],"a":3,"e":"Tekshirilmagan axborot ishonchsiz bo‘lishi mumkin."},{"q":"Qidiruv natijasida nimaga qarab sahifani ochish kerakligini aniqlash mumkin?","o":["Hech narsaga","Sarlavha va qisqa tavsifga","Faqat sahifa rangiga","Faqat tartib raqamiga"],"a":1,"e":"Sarlavha va tavsif sahifa mazmunini taxminan ko‘rsatadi."},{"q":"Web-sahifadagi matnni saqlashning qaysi usuli mavjud?","o":["Sichqonchani qo‘yib yuborish","Monitorni o‘chirish","Printerni ochish","Belgilab nusxalash va hujjatga joylash"],"a":3,"e":"Nusxalab hujjatga joylash umumiy usul."},{"q":"Filtrlash natijasida nima olinadi?","o":["Maqsadga mos va foydali axborot","Faqat keraksiz reklama","Bo‘sh sahifa","Virus"],"a":0,"e":"Filtrlash foydali ma’lumotni ajratib beradi."},{"q":"«Mening ishim uchun faqat 2024-yilgi yangi ma’lumot kerak». Qanday filtrlash qulay?","o":["Qidiruvda sana bo‘yicha sozlamani tanlash","Sana haqida o‘ylamaslik","Eski saytlarni ochish","Faqat rasm qidirish"],"a":0,"e":"Sana bo‘yicha filtr yangi axborotni ajratib beradi."}]},{"t":"29-dars. Elektron xatni yozish, tahrirlash, o‘qish, javob berish va matn bilan ishlash uskunalari. Foydalanuvchi manzillarini qo‘shish","lesson":"<p><b>Elektron pochta</b> (e-mail) — internet orqali xat va fayllarni almashish xizmati. Har bir foydalanuvchining o‘z <b>elektron manzili</b> bo‘ladi, masalan: <i>ali@example.uz</i>.</p>\n<h4>Manzil tuzilishi</h4>\n<ul><li><b>ali</b> — foydalanuvchi nomi (login).</li><li><b>@</b> — «at» belgisi, nom bilan serverni ajratadi.</li><li><b>example.uz</b> — pochta xizmati (server) domeni.</li></ul>\n<h4>Xat yozish</h4>\n<div class=\"ex\"><b>Qadamlar.</b><ol><li>Yangi xat yozish tugmasini bosing.</li><li>«Kimga» maydoniga qabul qiluvchi manzilini kiriting.</li><li>«Mavzu» maydoniga xatning qisqa sarlavhasini yozing.</li><li>Xat matnini yozing: salomlashing, fikrni aniq bayon qiling, hurmat bilan yakunlang.</li><li>«Yuborish» tugmasini bosing.</li></ol></div>\n<h4>Xat bilan ishlash</h4>\n<ul><li><b>O‘qish</b> — kelgan xatni ochish.</li><li><b>Javob berish</b> — xatga javob yozish (mavzu va manzil avtomatik to‘ldiriladi).</li><li><b>Tahrirlash</b> — yuborilmagan xat (qoralama) matnini o‘zgartirish. Yuborilgan xatni o‘zgartirib bo‘lmaydi.</li></ul>\n<p>Matn bilan ishlash uskunalari (qalin, kursiv, rang va ro‘yxat) xatni chiroyli qiladi. Tez-tez yozadigan odamlarning manzillarini <b>kontaktlar</b> ro‘yxatiga qo‘shib qo‘yish mumkin.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Manzilda @ belgisi bo‘ladi.</li><li>Mavzuni yozish odob qoidasi.</li></ul>","quiz":[{"q":"Elektron pochta nima?","o":["Rasm chizish dasturi","Hisoblash dasturi","Oddiy qog‘oz pochta","Internet orqali xat va fayl almashish xizmati"],"a":3,"e":"E-mail internet orqali xabar yuborish xizmati."},{"q":"Elektron pochta manzilida qaysi belgi albatta bo‘ladi?","o":["%","#","&","@"],"a":3,"e":"Foydalanuvchi nomi va domen @ belgisi bilan ajratiladi."},{"q":"«Kimga» maydoniga nima yoziladi?","o":["Xat matni","Qabul qiluvchining elektron manzili","Mavzu","Jo‘natuvchi paroli"],"a":1,"e":"Kimga maydoni qabul qiluvchi manzilini bildiradi."},{"q":"«Mavzu» maydoni nima uchun kerak?","o":["Xatning qisqa mazmunini ko‘rsatish uchun","Rasmni kichraytirish uchun","Faylni o‘chirish uchun","Parolni yozish uchun"],"a":0,"e":"Mavzu qabul qiluvchiga xat nima haqida ekanini bildiradi."},{"q":"Kelgan xatga javob berish uchun nima qilinadi?","o":["Kompyuter qayta ishga tushiriladi","«Javob» imkoniyatidan foydalaniladi","Xat o‘chiriladi","Yangi parol olinadi"],"a":1,"e":"Javob berishda manzil va mavzu avtomatik to‘ldiriladi."},{"q":"«ali@example.uz» manzilida «ali» nimani bildiradi?","o":["Fayl turini","Protokolni","Domen turini","Foydalanuvchi nomini"],"a":3,"e":"@ belgisidan oldingi qism foydalanuvchi nomi."},{"q":"Yuborilgan xat haqida qaysi mulohaza to‘g‘ri?","o":["U avtomatik o‘chadi","Uni yuborilgandan keyin o‘zgartirib bo‘lmaydi","U faqat rasm bo‘ladi","Uni har doim tahrirlab bo‘ladi"],"a":1,"e":"Yuborilgan xat matnini o‘zgartirib bo‘lmaydi, faqat qoralamani tahrirlash mumkin."},{"q":"Tez-tez yozadigan odamlarning manzillarini saqlash uchun nimadan foydalaniladi?","o":["Printerdan","Kontaktlar ro‘yxatidan","Qidiruv tizimidan","Skanerdan"],"a":1,"e":"Kontaktlar manzillarni saqlaydi va tez tanlash imkonini beradi."},{"q":"Xat yozish tartibini toping.","o":["Yangi xat, manzil, mavzu, matn, yuborish","Mavzu, yuborish, manzil","Matn, manzil, yangi xat","Yuborish, matn, mavzu, manzil"],"a":0,"e":"Avval yangi xat ochilib, maydonlar to‘ldiriladi va so‘ng yuboriladi."},{"q":"Xat matnini chiroyli bezash uchun nimadan foydalaniladi?","o":["Faqat printerdan","Antivirusdan","Faqat sichqonchadan","Matn bilan ishlash uskunalaridan (qalin, kursiv, rang)"],"a":3,"e":"Pochta muharririda ham matnni formatlash mumkin."}]},{"t":"30-dars. Ilova qilingan hujjatlarni ochish, elektron xatga hujjat ilova qilish","lesson":"<p>Elektron xat bilan faqat matn emas, <b>fayllar</b> ham yuborish mumkin: hujjat, rasm, jadval, taqdimot. Xatga qo‘shilgan fayl <b>ilova</b> (biriktirilgan fayl) deyiladi. Ilovali xatning yonida odatda qisqich (skrepka) belgisi ko‘rinadi.</p>\n<h4>Xatga hujjat ilova qilish</h4>\n<div class=\"ex\"><b>Qadamlar.</b><ol><li>Yangi xat oching, manzil va mavzuni to‘ldiring.</li><li>Fayl biriktirish tugmasini (odatda qisqich belgisi) bosing.</li><li>Kompyuterdan kerakli faylni tanlang.</li><li>Fayl nomi xat ostida ko‘rinishini tekshiring.</li><li>Xat yuboring.</li></ol></div>\n<h4>Kelgan ilovani ochish</h4>\n<ul><li>Ilovali xatni oching.</li><li>Fayl nomini bosib, uni ko‘ring yoki kompyuterga yuklab oling.</li><li>Yuklangan faylni tegishli dastur bilan oching.</li></ul>\n<h4>Xavfsizlik qoidalari</h4>\n<ul><li>Notanish jo‘natuvchidan kelgan ilovani ochmang — unda virus bo‘lishi mumkin.</li><li>Shubhali fayllar (masalan, .exe) bilan ehtiyot bo‘ling.</li><li>Antivirus dasturidan foydalaning.</li></ul>\n<p>Pochta xizmatlarida ilova hajmiga cheklov bor, katta fayllarni siqib (arxivlab) yuborish qulay.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Ilova — xatga biriktirilgan fayl.</li><li>Notanish ilovani ochishdan oldin o‘ylang.</li><li>Yuborishdan oldin fayl biriktirilganini tekshiring.</li></ul>","quiz":[{"q":"Xatga qo‘shilgan fayl nima deb ataladi?","o":["Parol","Domen","Mavzu","Ilova (biriktirilgan fayl)"],"a":3,"e":"Ilova xat bilan birga yuboriladigan fayl."},{"q":"Ilovali xatni odatda qaysi belgi bilan taniysiz?","o":["Yulduzcha","Qisqich (skrepka) belgisi","Chiroq","Qo‘ng‘iroq"],"a":1,"e":"Ilova mavjudligi qisqich belgisi bilan ko‘rsatiladi."},{"q":"Xatga hujjat ilova qilish tartibini toping.","o":["Faylni tanlash, parolni yozish","Yuborish, fayl tanlash, xat ochish","Faylni o‘chirish, yuborish","Xat ochish, fayl biriktirish, faylni tanlash, yuborish"],"a":3,"e":"Avval xat ochiladi, so‘ng fayl biriktirilib yuboriladi."},{"q":"Notanish jo‘natuvchidan ilovali xat keldi. Eng to‘g‘ri harakat qaysi?","o":["Darhol ochib ko‘rish","Ilovani ochmaslik va ehtiyot bo‘lish","Hammaga yuborish","Parolingizni yozib yuborish"],"a":1,"e":"Notanish ilovada virus bo‘lishi mumkin."},{"q":"Ilova qilingan faylni kompyuterga olish nima deyiladi?","o":["Yuklab olish","O‘chirish","Yuborish","Siqish"],"a":0,"e":"Faylni qurilmaga saqlash yuklab olish deyiladi."},{"q":"Hajmi katta fayllarni yuborishdan oldin nima qilish foydali?","o":["Siqib (arxivlab) yuborish","Printerga chiqarish","Faylni o‘chirish","Faylni o‘zgartirmasdan tashlab ketish"],"a":0,"e":"Arxivlash fayl hajmini kamaytiradi."},{"q":"Xatni yuborishdan oldin nimani tekshirish kerak?","o":["Monitor rangini","Fayl haqiqatan biriktirilganini","Klaviatura tilini o‘chirishni","Hech narsani"],"a":1,"e":"Ko‘pincha fayl biriktirishni unutib qo‘yishadi."},{"q":"Qaysi fayl turi ko‘proq ehtiyotkorlikni talab qiladi?","o":["Maktab topshirig‘i matni, o‘qituvchidan","Noma’lum dasturiy fayl (masalan, .exe)","Do‘stingiz yuborgan va kutilgan hujjat","Oddiy rasm, ishonchli manbadan"],"a":1,"e":"Ishga tushuvchi fayllarda virus bo‘lishi mumkin."},{"q":"Xatga bir nechta fayl biriktirish mumkinmi?","o":["Ha, bir nechta fayl biriktirish mumkin","Faqat arxiv","Faqat rasm","Yo‘q, faqat bitta"],"a":0,"e":"Ko‘pgina pochta xizmatlarida bir nechta fayl biriktiriladi."},{"q":"Virusdan himoyalanish uchun nima qilish kerak?","o":["Hamma ilovani ochish","Antivirusni o‘chirish","Antivirus dasturidan foydalanish va shubhali ilovalarni ochmaslik","Parolni hammaga aytish"],"a":2,"e":"Himoya antivirus va ehtiyotkorlik bilan ta’minlanadi."}]},{"t":"31-dars. Elektron pochta papkalarini boshqarish. Loyiha ishi","lesson":"<p>Elektron pochta qutisida xatlar ko‘payib ketganda, tartib saqlash uchun <b>papkalar</b> ishlatiladi.</p>\n<h4>Asosiy papkalar</h4>\n<ul><li><b>Kiruvchi (Inbox)</b> — kelgan xatlar.</li>\n<li><b>Yuborilgan (Sent)</b> — siz yuborgan xatlar.</li>\n<li><b>Qoralamalar (Drafts)</b> — hali yuborilmagan xatlar.</li>\n<li><b>Spam</b> — keraksiz, reklama xatlari.</li>\n<li><b>Savat (Trash)</b> — o‘chirilgan xatlar.</li></ul>\n<h4>Papkalarni boshqarish</h4>\n<ul><li>Yangi papka (masalan, «Maktab», «Do‘stlar») yaratish.</li><li>Xatni kerakli papkaga ko‘chirish.</li><li>Keraksiz xatlarni o‘chirish, muhimlarini saqlash.</li></ul>\n<div class=\"ex\"><b>Loyiha ishi: «Mening pochta tartibim».</b><ol><li>Pochta qutingizda «Maktab» nomli papka yarating.</li><li>O‘qituvchidan kelgan xatni shu papkaga ko‘chiring.</li><li>Sinfdoshingizga ilova bilan xat yozing.</li><li>Xatning «Yuborilgan» papkada paydo bo‘lganini tekshiring.</li><li>Natijani sinfda taqdim eting.</li></ol></div>\n<p>Aniq tugmalar pochta xizmatiga qarab farq qilishi mumkin, lekin papkalar g‘oyasi bir xil.</p>\n<h4>Eslab qoling</h4>\n<ul><li>Papkalar xatlarni tartibga soladi.</li><li>Spamni ochmaslik yaxshi.</li><li>O‘chirilgan xatlar avval savatga tushadi.</li></ul>","quiz":[{"q":"Kelgan xatlar qaysi papkada saqlanadi?","o":["Qoralamalar (Drafts)","Kiruvchi (Inbox)","Yuborilgan (Sent)","Spam"],"a":1,"e":"Inbox — qabul qilingan xatlar papkasi."},{"q":"Siz jo‘natgan xatlar qaysi papkada ko‘rinadi?","o":["Yuborilgan (Sent)","Savat","Kiruvchi","Spam"],"a":0,"e":"Sent papkasida yuborilgan xatlar saqlanadi."},{"q":"Hali yuborilmagan, yozilishi tugamagan xat qayerda turadi?","o":["Spam","Qoralamalar (Drafts)","Kiruvchi","Yuborilgan"],"a":1,"e":"Draft — qoralama xatlar."},{"q":"Spam papkasida nima bo‘ladi?","o":["Do‘stlaringiz xatlari","Faqat maktab xatlari","Faqat rasm fayllar","Keraksiz, reklama xarakteridagi xatlar"],"a":3,"e":"Spam — keraksiz yoki shubhali xatlar."},{"q":"Xatlarni tartibga solish uchun nima qilinadi?","o":["Barcha xatlar bitta joyda qoldiriladi","Parol o‘zgartiriladi","Mavzu bo‘yicha yangi papkalar yaratilib, xatlar ko‘chiriladi","Hamma xat o‘chiriladi"],"a":2,"e":"Papkalar xatlarni guruhlashga yordam beradi."},{"q":"O‘chirilgan xat odatda avval qayerga tushadi?","o":["Savat (Trash)","Yuborilgan","Kiruvchi","Qoralamalar"],"a":0,"e":"O‘chirilgan xatlar avval savatda turadi."},{"q":"«Maktab» papkasi nima uchun yaratiladi?","o":["Parolni almashtirish uchun","Kompyuterni tezlashtirish uchun","Rasmni chizish uchun","O‘qishga oid xatlarni bir joyda saqlash uchun"],"a":3,"e":"Mavzuli papka kerakli xatni tez topishga yordam beradi."},{"q":"Quyidagi mulohazalardan qaysi biri to‘g‘ri?","o":["Pochtada papkalar bo‘lmaydi","Papkalar g‘oyasi turli pochta xizmatlarida o‘xshash","Papkalar faqat bitta xizmatda bor","Papka yaratib bo‘lmaydi"],"a":1,"e":"Aniq tugmalar farq qilsa-da, papkalar mantig‘i bir xil."},{"q":"Siz sinfdoshingizga xat yubordingiz. Uni qaerdan topasiz?","o":["Yuborilgan papkasidan","Spamdan","Qoralamalardan, albatta","Kiruvchidan"],"a":0,"e":"Yuborilgan xatlar Sent papkasida saqlanadi."},{"q":"Spam papkasidagi noma’lum xatdagi havolalarga munosabat qanday bo‘lishi kerak?","o":["Parol yuborish","Ehtiyot bo‘lish va ochmaslik","Do‘stlarga tarqatish","Hammasini bosib ko‘rish"],"a":1,"e":"Spamda zararli havolalar bo‘lishi mumkin."}]},{"t":"32-dars. Taqdimotni yaratish rejasi. Maketni tanlash va slaydga matn, tasvir, ovoz qo‘shish","lesson":"<p><b>Taqdimot</b> — ma’lumotni slaydlar ketma-ketligi orqali ko‘rgazmali yetkazish. Yaxshi taqdimot oldindan <b>rejalashtiriladi</b>.</p>\n<h4>Taqdimot yaratish rejasi</h4>\n<ol><li><b>Mavzu va maqsad</b>ni aniqlash.</li><li><b>Auditoriya</b>ni o‘ylash (kimga mo‘ljallangan).</li><li>Slaydlar soni va tartibini belgilash: sarlavha, mazmun, xulosa.</li><li>Matn, tasvir va ovoz materiallarini tayyorlash.</li><li>Slaydlarni yaratish va tekshirish.</li></ol>\n<h4>Maket tanlash</h4>\n<p><b>Maket</b> (slayd tuzilmasi) — slaydda matn va tasvir qayerda joylashishini belgilaydi. Masalan, sarlavha slaydi, matn va rasm slaydi. Mazmunga mos maket tanlanadi.</p>\n<h4>Slaydga element qo‘shish</h4>\n<div class=\"ex\"><b>Qadamlar.</b><ol><li>Yangi slayd qo‘shib, maketni tanlang.</li><li>Sarlavha va qisqa matn kiriting.</li><li>Kompyuterdagi rasmni qo‘shing.</li><li>Kerak bo‘lsa, ovoz faylini qo‘shing.</li><li>Slaydni ko‘rib chiqing.</li></ol></div>\n<h4>Maslahatlar</h4>\n<ul><li>Slaydda matn kam, shrift katta va o‘qishga qulay bo‘lsin.</li><li>Orqa fon va matn rangi bir-biridan yaxshi ajralib tursin.</li><li>Rasm mavzuga mos bo‘lsin.</li></ul>\n<h4>Eslab qoling</h4>\n<ul><li>Avval reja, keyin slayd.</li><li>Maket slayd tuzilmasini beradi.</li><li>Matnni ixcham yozing.</li></ul>","quiz":[{"q":"Taqdimot yaratishdan oldin nima qilish kerak?","o":["Kompyuterni o‘chirish","Mavzu, maqsad va auditoriyani aniqlab reja tuzish","Darhol hamma slaydni to‘ldirish","Faqat rasm yig‘ish"],"a":1,"e":"Yaxshi taqdimot oldindan rejalashtiriladi."},{"q":"Maket nima?","o":["Fayl nomi","Slayd tuzilmasi: matn va tasvir joylashuvi","Elektron xat turi","Slayd ovozi"],"a":1,"e":"Maket slayddagi elementlar joyini belgilaydi."},{"q":"Taqdimot rejasining to‘g‘ri tartibi qaysi?","o":["Materiallar, o‘chirish, saqlash","Ovoz, shrift, yopish","Yaratish, mavzu, auditoriya","Mavzu va maqsad, auditoriya, slaydlar rejasi, materiallar, yaratish"],"a":3,"e":"Avval maqsad va auditoriya, keyin slaydlar va materiallar."},{"q":"Slaydda matn qanday bo‘lishi kerak?","o":["O‘qib bo‘lmaydigan rangda","Ixcham va o‘qishga qulay","Juda uzun, mayda shriftda","Faqat bitta harf"],"a":1,"e":"Ko‘p matn tomoshabinni charchatadi."},{"q":"Taqdimotga ovoz qo‘shish nima uchun foydali?","o":["Mazmunni boyitish va e’tiborni jalb qilish uchun","Rasmni o‘chirish uchun","Dasturni o‘chirish uchun","Faylni kichraytirish uchun"],"a":0,"e":"Ovoz qo‘shimcha ma’lumot yoki bezak bo‘lishi mumkin."},{"q":"Slayd fon rangi va matn rangi qanday bo‘lishi kerak?","o":["Bir xil rangda","Matn ko‘rinmaydigan","Albatta yorqin qizil","Bir-biridan yaxshi ajralib turadigan"],"a":3,"e":"Kontrast matnni o‘qishni osonlashtiradi."},{"q":"Taqdimotda auditoriyani hisobga olish nimani anglatadi?","o":["Tomoshabinlarning yoshi va qiziqishiga mos mazmun tanlash","Auditoriyasiz tayyorlash","Hech kimga ko‘rsatmaslik","Faqat o‘zingiz uchun yozish"],"a":0,"e":"Auditoriyaga mos til va mazmun tanlanadi."},{"q":"Tipik taqdimot slaydlari tarkibida nima bo‘ladi?","o":["Faqat jadval","Faqat parol","Faqat bitta rasm","Sarlavha, mazmun va xulosa"],"a":3,"e":"Odatda sarlavha, asosiy qism va xulosa bor."},{"q":"Slaydga rasm tanlashda nimaga e’tibor beriladi?","o":["Rasm albatta eng katta hajmli bo‘lishi","Rasm mavzuga mos bo‘lishi","Rasmning bo‘lmasligi","Rasm mavzuga aloqasiz bo‘lishi"],"a":1,"e":"Mavzuga mos rasm tushunishga yordam beradi."},{"q":"Slaydni yaratish tartibini toping.","o":["Yangi slayd, maket tanlash, matn, tasvir, ovoz qo‘shish","Ovoz, o‘chirish, saqlash","Matn, o‘chirish, yopish","Maket tanlash, dasturni o‘chirish"],"a":0,"e":"Avval slayd va maket, so‘ng elementlar qo‘shiladi."}]},{"t":"33-dars. Nazorat ishi","lesson":"<p><b>Nazorat ishi 4</b> quyidagi darslarni qamrab oladi:</p><ul><li>Web manzillar haqida tushuncha. Qidirish tizimini ishlash tamoyili va axborotning ishonchliligi.</li><li>Axborotni filtrlash. Web-sahifa, web-sayt, URL manzilidagi matnlarni saqlash</li><li>Elektron xatni yozish, tahrirlash, o‘qish, javob berish va matn bilan ishlash uskunalari. Foydalanuvchi manzillarini qo‘shish</li><li>Ilova qilingan hujjatlarni ochish, elektron xatga hujjat ilova qilish</li><li>Elektron pochta papkalarini boshqarish. Loyiha ishi</li><li>Taqdimotni yaratish rejasi. Maketni tanlash va slaydga matn, tasvir, ovoz qo‘shish</li></ul><p>Test <b>20 ta savoldan</b> iborat. Savollar o‘tilgan mavzulardan olingan. Keyingi darsga o‘tish uchun barcha savollarga to‘g‘ri javob berish kerak.</p>","quiz":[{"q":"Maket nima?","o":["Fayl nomi","Slayd tuzilmasi: matn va tasvir joylashuvi","Elektron xat turi","Slayd ovozi"],"a":1,"e":"Maket slayddagi elementlar joyini belgilaydi."},{"q":"Notanish jo‘natuvchidan ilovali xat keldi. Eng to‘g‘ri harakat qaysi?","o":["Darhol ochib ko‘rish","Ilovani ochmaslik va ehtiyot bo‘lish","Hammaga yuborish","Parolingizni yozib yuborish"],"a":1,"e":"Notanish ilovada virus bo‘lishi mumkin."},{"q":"Kelgan xatga javob berish uchun nima qilinadi?","o":["Kompyuter qayta ishga tushiriladi","«Javob» imkoniyatidan foydalaniladi","Xat o‘chiriladi","Yangi parol olinadi"],"a":1,"e":"Javob berishda manzil va mavzu avtomatik to‘ldiriladi."},{"q":"Kelgan xatlar qaysi papkada saqlanadi?","o":["Qoralamalar (Drafts)","Kiruvchi (Inbox)","Yuborilgan (Sent)","Spam"],"a":1,"e":"Inbox — qabul qilingan xatlar papkasi."},{"q":"Qaysi usul filtrlashga yordam beradi?","o":["Aniq kalit so‘zlar bilan qidirish","Hech narsa o‘qimaslik","Har qanday sahifani ochib chiqish","Barcha reklamaga bosish"],"a":0,"e":"Aniq so‘rov natijani toraytiradi."},{"q":"Qidiruv natijasida nimaga qarab sahifani ochish kerakligini aniqlash mumkin?","o":["Hech narsaga","Sarlavha va qisqa tavsifga","Faqat sahifa rangiga","Faqat tartib raqamiga"],"a":1,"e":"Sarlavha va tavsif sahifa mazmunini taxminan ko‘rsatadi."},{"q":"Siz sinfdoshingizga xat yubordingiz. Uni qaerdan topasiz?","o":["Yuborilgan papkasidan","Spamdan","Qoralamalardan, albatta","Kiruvchidan"],"a":0,"e":"Yuborilgan xatlar Sent papkasida saqlanadi."},{"q":"Xatga qo‘shilgan fayl nima deb ataladi?","o":["Parol","Domen","Mavzu","Ilova (biriktirilgan fayl)"],"a":3,"e":"Ilova xat bilan birga yuboriladigan fayl."},{"q":"Qidirish tizimi indeksi nima?","o":["Brauzer tugmasi","Kompyuter klaviaturasi","Internet sahifalari haqidagi katta ma’lumotlar bazasi","Elektron xat papkasi"],"a":2,"e":"Indeksda sahifalar haqida ma’lumot saqlanadi."},{"q":"«Mening ishim uchun faqat 2024-yilgi yangi ma’lumot kerak». Qanday filtrlash qulay?","o":["Qidiruvda sana bo‘yicha sozlamani tanlash","Sana haqida o‘ylamaslik","Eski saytlarni ochish","Faqat rasm qidirish"],"a":0,"e":"Sana bo‘yicha filtr yangi axborotni ajratib beradi."},{"q":"Quyidagilardan qaysi biri qidirish tizimi?","o":["Paint","Scratch","Google","Word"],"a":2,"e":"Google internetda qidirish tizimidir."},{"q":"Xat yozish tartibini toping.","o":["Yangi xat, manzil, mavzu, matn, yuborish","Mavzu, yuborish, manzil","Matn, manzil, yangi xat","Yuborish, matn, mavzu, manzil"],"a":0,"e":"Avval yangi xat ochilib, maydonlar to‘ldiriladi va so‘ng yuboriladi."},{"q":"«Kimga» maydoniga nima yoziladi?","o":["Xat matni","Qabul qiluvchining elektron manzili","Mavzu","Jo‘natuvchi paroli"],"a":1,"e":"Kimga maydoni qabul qiluvchi manzilini bildiradi."},{"q":"Qaysi holda axborotni filtrlash noto‘g‘ri bajarilgan?","o":["Sana bo‘yicha yangi natijani tanlash","Bir nechta manbani solishtirish","Ishonchli saytni tanlash","Reklama sahifasidagi ma’lumotni tekshirmay haqiqat deb qabul qilish"],"a":3,"e":"Tekshirilmagan axborot ishonchsiz bo‘lishi mumkin."},{"q":"Spam papkasida nima bo‘ladi?","o":["Do‘stlaringiz xatlari","Faqat maktab xatlari","Faqat rasm fayllar","Keraksiz, reklama xarakteridagi xatlar"],"a":3,"e":"Spam — keraksiz yoki shubhali xatlar."},{"q":"Taqdimot rejasining to‘g‘ri tartibi qaysi?","o":["Materiallar, o‘chirish, saqlash","Ovoz, shrift, yopish","Yaratish, mavzu, auditoriya","Mavzu va maqsad, auditoriya, slaydlar rejasi, materiallar, yaratish"],"a":3,"e":"Avval maqsad va auditoriya, keyin slaydlar va materiallar."},{"q":"https manzilidagi «s» harfi nimani bildiradi?","o":["Surat borligini","Himoyalangan ulanishni","Sekin ishlashni","Saytning rangini"],"a":1,"e":"https — himoyalangan protokol."},{"q":"Taqdimotga ovoz qo‘shish nima uchun foydali?","o":["Mazmunni boyitish va e’tiborni jalb qilish uchun","Rasmni o‘chirish uchun","Dasturni o‘chirish uchun","Faylni kichraytirish uchun"],"a":0,"e":"Ovoz qo‘shimcha ma’lumot yoki bezak bo‘lishi mumkin."},{"q":"Qidirish tizimi natijani qanday topadi?","o":["O‘z indeksidagi sahifalardan mosini tanlab beradi","Faqat kitobdan","Faqat televizordan","Kompyuteringizdagi fayllardan"],"a":0,"e":"Indeks — qidiruv tizimi yig‘gan sahifalar bazasi."},{"q":"Xatni yuborishdan oldin nimani tekshirish kerak?","o":["Monitor rangini","Fayl haqiqatan biriktirilganini","Klaviatura tilini o‘chirishni","Hech narsani"],"a":1,"e":"Ko‘pincha fayl biriktirishni unutib qo‘yishadi."}]},{"t":"34-dars. Takrorlash","lesson":"<p><b>Takrorlash</b> quyidagi darslarni qamrab oladi:</p><ul><li>Matn qo‘shish, o‘zgartrish va ko‘chirish</li><li>Shrift turi, o‘lchami va rangini o‘zgartrish. Matnni tekislash</li><li>Hujjatga tasvir va hoshiya qo‘shish</li><li>Hujjatlarni auditoriya uchun moslash</li><li>Loyiha ishi. Amaliy mashg‘ulot</li><li>Tasvirni import qilish</li><li>Ishning boshlang‘ich nusxalari.</li><li>Tasvirlarni aylantirish, teskari o‘girish. Tasvirni o‘lchamlarini o‘zgartish</li><li>Elektron jadval tushunchasi. Ma‘lumotlarni elektron jadvalga kiritish</li><li>Sodda formulalarni kiritishda katak manzilidan foydalanish. Formulalarni nusxalash</li><li>Grafik yaratish.</li><li>Amaliy mashg‘ulot</li><li>Ma‘lumotlar turlari va bazasi, maydonlarni aniqlash</li><li>Ma‘lumotlar bazasidan harakatlanish va teng sharti bilan query yaratish. Query-ma‘lumotlar bazasidan aniq ma‘lumotni qidirish uskunasi</li><li>Scratch dasturida takrorlash amaliyotidan foydalanish</li><li>Scratch dasturida PEN uskunasidan foydalanish</li><li>Scratch dasturida shakllar bilan ishlash</li><li>Scratch dasturida takrorlash bloki yordamida yangi shakl chizish</li><li>Scratch dasturida protseduralar bilan ishlash</li><li>Dekompozitsiyadan foydalanish. Kichik masala yechimi orqali katta masalaga o‘tish</li><li>Web manzillar haqida tushuncha. Qidirish tizimini ishlash tamoyili va axborotning ishonchliligi.</li><li>Axborotni filtrlash. Web-sahifa, web-sayt, URL manzilidagi matnlarni saqlash</li><li>Elektron xatni yozish, tahrirlash, o‘qish, javob berish va matn bilan ishlash uskunalari. Foydalanuvchi manzillarini qo‘shish</li><li>Ilova qilingan hujjatlarni ochish, elektron xatga hujjat ilova qilish</li><li>Elektron pochta papkalarini boshqarish. Loyiha ishi</li><li>Taqdimotni yaratish rejasi. Maketni tanlash va slaydga matn, tasvir, ovoz qo‘shish</li></ul><p>Test <b>10 ta aralash savoldan</b> iborat. Qiynalgan mavzuingizning darsini qayta o‘qib chiqing.</p>","quiz":[{"q":"Loyiha ishining birinchi bosqichi qaysi?","o":["Taqdim etish","Chop etish","Mavzu va maqsadni tanlash","Faylni o‘chirish"],"a":2,"e":"Avval nima qilinishi aniqlanadi."},{"q":"Satrlar nima bilan belgilanadi?","o":["Ranglar bilan","Raqamlar bilan","Rasmlar bilan","Harflar bilan"],"a":1,"e":"Satrlar 1, 2, 3 kabi raqamlanadi."},{"q":"Do‘stlar bazasida «Telefon raqami» maydoni bor. Bu maydonda nima saqlanadi?","o":["Do‘stlarning barcha ismlari","Jadval nomi","Yozuvlar soni","Har bir do‘stning raqami"],"a":3,"e":"Maydon har bir yozuvdagi bitta xususiyatni saqlaydi."},{"q":"Sprayt 5 marta «move 10 steps» bajarsa, jami necha qadam yuradi?","o":["10 qadam","5 qadam","50 qadam","15 qadam"],"a":2,"e":"5 marta 10 qadam — 50 qadam."},{"q":"Rasmni ko‘zgudagi aksidek almashtirish qaysi amal?","o":["Aylantirish (Rotate)","Teskari o‘girish (Flip)","Kesish (Cut)","Qo‘yish (Paste)"],"a":1,"e":"Flip rasmning akslantirilgan ko‘rinishini beradi."},{"q":"To‘g‘ri tartibni tanlang: 1) tur tanlash 2) ma’lumotlarni belgilash 3) sarlavha berish.","o":["1, 2, 3","3, 1, 2","2, 1, 3","2, 3, 1"],"a":2,"e":"Avval ma’lumot, keyin tur, so‘ng sarlavha."},{"q":"Xat yozish tartibini toping.","o":["Yangi xat, manzil, mavzu, matn, yuborish","Mavzu, yuborish, manzil","Matn, manzil, yangi xat","Yuborish, matn, mavzu, manzil"],"a":0,"e":"Avval yangi xat ochilib, maydonlar to‘ldiriladi va so‘ng yuboriladi."},{"q":"Bo‘lish amali qaysi belgi bilan yoziladi?","o":["=","/","-","*"],"a":1,"e":"Bo‘lish uchun qiya chiziq ishlatiladi."},{"q":"Spam papkasida nima bo‘ladi?","o":["Do‘stlaringiz xatlari","Faqat maktab xatlari","Faqat rasm fayllar","Keraksiz, reklama xarakteridagi xatlar"],"a":3,"e":"Spam — keraksiz yoki shubhali xatlar."},{"q":"Hujjatni o‘qishga qulay qilish uchun qaysi tavsiya to‘g‘ri?","o":["Bir-ikki xil shrift va mos o‘lcham tanlash","Har so‘zga boshqa shrift berish","Eng kichik o‘lchamni tanlash","Barcha matnni qizil qilish"],"a":0,"e":"Bir xillik va o‘qilish qulayligi muhim."}]}];
